// Üretilen dosya: tool/ozgun/uret.py. Bilim · Meteoroloji: hava olayları, bulutlar, rüzgâr sistemleri, hava tahmini (orta).
const ozScience8Orta = <(String, String, List<String>, String)>[
  ('Atmosfer kütlesinin yaklaşık yarısı deniz seviyesinden itibaren hangi yüksekliğin altında bulunur?', 'Yaklaşık 5,5 km', ['Yaklaşık 1 km', 'Yaklaşık 50 km', 'Yaklaşık 100 km'], 'Hava basıncı yaklaşık 5,5 km\'de deniz seviyesindekinin yarısına (500 hPa civarı) iner; bu, atmosfer kütlesinin yarısının bu yüksekliğin altında olduğu anlamına gelir.'),
  ('Atmosferin yaklaşık 100 km yüksekliğe kadar olan kesiminde ana gazların oranlarının hemen hemen değişmemesinin nedeni nedir?', 'Karışmanın gazları sürekli harmanlaması', ['Gazların tümünün aynı yoğunlukta olması', 'Güneş ışınlarının bu kesime ulaşmaması', 'Yerçekiminin bu yüksekliklerde etkisiz olması'], 'Türbülans ve taşınım havayı sürekli karıştırdığından yaklaşık 100 km\'ye kadar (homosfer) bileşim tekdüzedir; daha yukarıda gazlar ağırlıklarına göre ayrışmaya başlar.'),
  ('Deniz seviyesine yakın yerlerde basınç her 8 metrede yaklaşık 1 hPa azalır. Kıyıda 1015 hPa ölçülen bir günde 160 m yükseklikteki bir tepede yaklaşık kaç hPa ölçülür?', '995 hPa', ['1035 hPa', '1007 hPa', '975 hPa'], '160 / 8 = 20 hPa azalma olur; 1015 − 20 = 995 hPa.'),
  ('Everest Dağı\'nın zirvesinde hava basıncı deniz seviyesindekinin yaklaşık ne kadarıdır?', 'Üçte biri', ['Yarısı', 'Onda biri', 'Dörtte üçü'], 'Yaklaşık 8,8 km yükseklikteki zirvede basınç 330 hPa civarındadır; bu da deniz seviyesindeki 1013 hPa\'nın yaklaşık üçte biridir.'),
  ('Kuzey Yarımküre\'de Güneş ışınlarının en dik geldiği gün haziranda olduğu hâlde en sıcak ayların genellikle temmuz ve ağustos olmasına ne ad verilir?', 'Mevsimsel gecikme', ['Gün dönümü kayması', 'Isı adası etkisi', 'Karasallık sapması'], 'Kara ve denizler yaz başında depoladıkları ısıyı biriktirmeyi sürdürür; enerji fazlası haziran sonrasında da devam ettiğinden sıcaklık zirvesi birkaç hafta gecikir.'),
  ('Aynı enlemde bulunan bir kıyı kenti ile bir iç bölge kenti karşılaştırıldığında yıllık sıcaklık farkının kıyıda daha küçük olmasının nedeni nedir?', 'Suyun ısınıp soğuması karadan çok daha yavaştır', ['Kıyıda güneşlenme süresi daha kısadır', 'Deniz havası basıncı her mevsimde sabit tutarak sıcaklığı dengeler', 'İç bölgelerde rüzgâr hiç esmez'], 'Suyun özgül ısısı yüksektir ve ısı derinlere karışır; deniz yazın serinletici, kışın ısıtıcı etki yapar. Buna denizellik, tersine karasallık denir.'),
  ('Doğal sera etkisi olmasaydı Dünya\'nın ortalama yüzey sıcaklığının yaklaşık −18 °C olacağı hesaplanır. Gerçek ortalama yaklaşık 15 °C olduğuna göre doğal sera etkisi yüzeyi yaklaşık kaç derece ısıtmaktadır?', '33 °C', ['18 °C', '15 °C', '3 °C'], '15 − (−18) = 33 °C; bu fark su buharı, karbondioksit gibi gazların yerin yaydığı kızılötesi ışınımı tutmasından kaynaklanır.'),
  ('Doymamış bir hava parseli yükselirken soğuma hızı yaklaşık 10 °C/km iken, doymuş bir parselde bu hız belirgin biçimde daha azdır. Farkın nedeni nedir?', 'Yoğuşma sırasında açığa çıkan gizli ısının soğumayı kısmen dengelemesi', ['Doymuş havanın genleşmeyip sıkışması', 'Su damlacıklarının Güneş ışınımını soğurarak parseli dışarıdan ısıtması', 'Doymuş havanın yükselirken yavaşlaması'], 'Doymuş parselde buhar yoğuşur ve buharlaşmada alınmış olan gizli ısıyı geri verir; bu ısı genleşmeyle olan soğumanın bir kısmını karşılar.'),
  ('Kümülüs bulutlarının taban yüksekliği yaklaşık olarak 125 m × (sıcaklık − çiğ noktası) ile tahmin edilir. Yerde sıcaklığın 26 °C, çiğ noktasının 14 °C olduğu bir öğleden sonra bulut tabanı yaklaşık kaç metrede beklenir?', '1500 m', ['1200 m', '1750 m', '3250 m'], 'Fark 26 − 14 = 12 °C\'dir; 125 × 12 = 1500 m.'),
  ('Havanın taşıyabileceği en fazla su buharı (doymuş buhar basıncı) sıcaklıkla nasıl değişir?', 'Her 1 °C artışta yaklaşık %7 artar', ['Sıcaklıktan bağımsız olarak sabit kalır', 'Sıcaklık arttıkça doğrusal olarak azalır', 'Yalnız 0 °C\'nin altında değişir'], 'Clausius-Clapeyron bağıntısına göre doymuş buhar basıncı sıcaklıkla üstel artar; yaklaşık %7/°C kuralı bu artışı özetler.'),
  ('Islak termometre sıcaklığı neyi gösterir?', 'Havaya buharlaşma yoluyla soğutularak ulaşılabilecek en düşük sıcaklığı', ['Çiğ noktasının iki katını', 'Gölgede, rüzgârdan korunmuş bir yerde ölçülen günün en yüksek sıcaklığını', 'Yağmur suyunun ortalama sıcaklığını'], 'Islak bezle sarılı haznedeki su buharlaştıkça termometre soğur; hava doymuş değilse ıslak termometre sıcaklığı kuru termometreden düşüktür.'),
  ('Islak termometre sıcaklığının 35 °C civarına çıktığı koşullarda sağlıklı bir insanın gölgede dinlense bile uzun süre dayanamayacağı söylenir. Bunun nedeni nedir?', 'Ter buharlaşarak bedeni yeterince soğutamaz', ['Havadaki oksijen oranı belirgin biçimde düşer', 'Deri morötesi ışınları soğurmaz', 'Kan basıncı hava basıncıyla eşitlenir'], 'Bu değerde hava o kadar sıcak ve nemlidir ki terin buharlaşması bedenin ürettiği ısıyı uzaklaştırmaya yetmez; vücut ısısı yükselmeye başlar.'),
  ('Buharlaşmalı (evaporatif) soğutucular en verimli hangi iklim koşulunda çalışır?', 'Sıcak ve kuru havada', ['Sıcak ve çok nemli havada', 'Soğuk ve sisli havada', 'Yağmurlu ve rüzgârsız havada'], 'Bu soğutucular suyu buharlaştırarak havayı serinletir; kuru havada buharlaşma hızlı ve ıslak termometre sıcaklığı düşük olduğundan soğutma etkisi büyüktür.'),
  ('Yazın aynı 30 °C sıcaklıktaki iki günden birinde çiğ noktası 24 °C, ötekinde 10 °C\'dir. İnsanların hangi günü daha bunaltıcı bulması beklenir ve neden?', 'Çiğ noktası 24 °C olan günü; ter daha zor buharlaşır', ['Çiğ noktası 10 °C olan günü; hava daha kurudur', 'İkisini aynı bulurlar; sıcaklıkları eşittir', 'Çiğ noktası 10 °C olan günü; kuru hava nemi tene yapıştırır'], 'Yüksek çiğ noktası havada çok buhar olduğunu gösterir; bu durumda ter yavaş buharlaşır ve bunaltı hissi artar.'),
  ('Güneş\'i buzlu camın arkasından bakılıyormuş gibi soluk bir disk olarak gösteren, gri-mavimsi, düzgün orta seviye bulut örtüsü hangisidir?', 'Altostratus', ['Kümülüs', 'Sirrokümülüs', 'Kümülonimbus'], 'Altostratus orta seviyede (yaklaşık 2–7 km) yayılan bir örtüdür; Güneş belirsiz bir parlaklık olarak görünür ve cisimler gölge vermez.'),
  ('Çok yüksekte, küçük beyaz tanecikler ya da balık pullarına benzeyen dalgacıklar hâlinde görülen, gölgesiz bulut hangisidir?', 'Sirrokümülüs', ['Altostratus', 'Stratokümülüs', 'Kümülüs'], 'Sirrokümülüs buz kristallerinden oluşur; denizcilerin \'uskumru gökyüzü\' dediği desen bu bulutla ilişkilidir.'),
  ('Gökyüzünü kalın ve karanlık bir örtüyle kaplayan, Güneş\'i tamamen gizleyen ve saatlerce süren sürekli yağmur ya da kar bırakan bulut hangisidir?', 'Nimbostratus', ['Sirrus', 'Altokümülüs kastellanus', 'Kümülüs'], 'Nimbostratus geniş alana yayılmış kalın bir yağış bulutudur; sağanak değil, uzun süreli ve düzenli yağış verir.'),
  ('Hale ışık halkasını en sık oluşturan, gökyüzüne ince ve süt beyazı bir tül gibi yayılan yüksek bulut hangisidir?', 'Sirrostratus', ['Nimbostratus', 'Stratokümülüs', 'Altokümülüs'], 'Sirrostratus altıgen buz kristallerinden oluşan ince bir örtüdür; kristaller ışığı kırarak Güneş ya da Ay çevresinde halka oluşturur.'),
  ('Alçak seviyede, gri ya da beyazımsı yuvarlak topakların bir tabaka hâlinde birleştiği, aralarından yer yer mavi göğün göründüğü ve dünyada en yaygın görülen bulut cinsi hangisidir?', 'Stratokümülüs', ['Sirrokümülüs', 'Altostratus translusidus', 'Kümülonimbus'], 'Stratokümülüs, okyanuslar üzerinde geniş alanlar kaplar ve uydu görüntülerinde en çok görülen bulut cinsidir; genellikle yağış vermez ya da hafif yağış verir.'),
  ('Bulut adlarındaki \'alto\' öneki Latincede \'yüksek\' anlamına gelir. Buna karşın altokümülüs ve altostratus hangi seviyede sınıflandırılır?', 'Orta seviyede', ['En yüksek seviyede', 'Yere değen seviyede', 'Stratosferde'], 'Adlandırma tarihî bir alışkanlıktır: \'alto\' önekli bulutlar alçak bulutlardan yüksek, sirrus türlerinden alçak olan orta katmanda yer alır.'),
  ('Gökyüzünde altostratus örtüsü varken yere gölge düşmemesi, ince sirrostratus örtüsü varken ise belirgin gölgeler oluşması neyi gösterir?', 'Altostratusun Güneş ışığını daha fazla engellediğini', ['Sirrostratusun daha alçakta olduğunu', 'Altostratusun yalnız buzdan oluştuğunu', 'Sirrostratusun yalnızca sıvı su damlacıklarından oluştuğunu'], 'Sirrostratus ince bir buz tülü olduğundan doğrudan ışığın çoğunu geçirir; daha kalın altostratus ise ışığı dağıtarak keskin gölgeleri yok eder.'),
  ('Dağların rüzgâr altında, saatlerce aynı yerde duruyormuş gibi görünen, mercek ya da uçan daire biçimli düzgün bulutlara ne ad verilir?', 'Lentikular bulut', ['Mammatus bulutu', 'Pirokümülüs', 'Kümülüs fraktus'], 'Lentikular (mercek) bulutlar dağ dalgalarının tepe noktalarında oluşur; hava bulutun içinden akıp geçse de bulut aynı yerde yenilenir.'),
  ('Lentikular bir bulutun güçlü rüzgâra rağmen yerinden kımıldamıyormuş gibi görünmesinin açıklaması hangisidir?', 'Hava bulutun bir yanında yoğuşup öbür yanında buharlaşarak sürekli geçer', ['Bulut dağın zirvesine yerçekimiyle bağlıdır', 'Bulutun içindeki hava tamamen durgundur', 'Bulut buzdan oluştuğu için rüzgârdan etkilenmez ve yerinde kalır'], 'Dalganın yükselen kolunda hava soğuyup yoğuşur, alçalan kolunda ısınıp buharlaşır; böylece bulut, havanın akışına karşın sabit bir \'duran dalga\' gibi kalır.'),
  ('Sabah saatlerinde altokümülüs bulutlarının üst kısımlarında küçük kale burçlarını andıran kabarıklıklar (kastellanus) görülmesi meteorologlar için neyin işaretidir?', 'Orta seviyede kararsızlık ve gün içinde gök gürültülü sağanak olasılığı', ['Önümüzdeki günlerde kesintisiz açık hava', 'Yüksek basıncın güçlenip yağışın en az bir hafta kesileceği', 'Yüzeyde yoğun radyasyon sisi oluşacağı'], 'Kastellanus, orta katmandaki havanın kararsız olduğunu ve dikey gelişime elverişli olduğunu gösterir; bu yüzden öğleden sonra fırtına habercisi sayılır.'),
  ('Süper hücre fırtınalarında yağışsız taban bölgesinden aşağı sarkan, çoğu zaman yavaşça dönen bulut çıkıntısına ne ad verilir ve neden önemlidir?', 'Duvar bulutu; hortum oluşabilecek bölgeyi gösterebilir', ['Örs bulutu; fırtınanın dağıldığını gösterir', 'Bayrak bulutu; dağ dalgasının zirveye takıldığını gösterir', 'Pileus; yağışın bittiğini gösterir'], 'Duvar bulutu, fırtınanın içine çekilen nemli havanın daha alçakta yoğuşmasıyla oluşur; dönmesi mezosiklonun varlığına işaret ettiğinden gözlemciler için önemlidir.'),
  ('Havalimanlarında bulut tabanının yüksekliğini yukarı doğru gönderdiği lazer ya da ışık atımlarının yansımasından ölçen alete ne ad verilir?', 'Seilometre', ['Anemometre', 'Plüviyometre', 'Higrograf'], 'Seilometre (tavan ölçer) atımın gidip dönme süresinden bulut tabanının yüksekliğini hesaplar; bu bilgi iniş-kalkış güvenliği için önemlidir.'),
  ('Havacılık raporlarında \'tavan\' (ceiling) olarak tanımlanan yükseklik hangisidir?', 'Gökyüzünün yarıdan fazlasını kaplayan en alçak bulut katmanının tabanı', ['Görülen en yüksek bulutun tepesi', 'Tropopozun yüksekliği', 'Uçağın taşıdığı yükle çıkabileceği en büyük uçuş yüksekliği'], 'Havacılıkta tavan, \'parçalı kapalı\' (BKN, 5–7 okta) ya da \'kapalı\' (OVC, 8 okta) olarak raporlanan en alçak katmanın tabanıdır.'),
  ('Bir bulutun 1 km³ hacminde metreküp başına ortalama 0,5 gram sıvı su bulunduğu ölçülmüştür. Bu buluttaki sıvı suyun toplam kütlesi yaklaşık ne kadardır?', '500 ton', ['5 ton', '50 ton', '5000 ton'], '1 km³ = 10⁹ m³; 10⁹ × 0,5 g = 5 × 10⁸ g = 500 000 kg = 500 ton.'),
  ('Yüksekte uçan uçakların arkasındaki yoğuşma izlerinin bazı günlerde hemen kaybolup bazı günlerde saatlerce kalarak yayılmasını belirleyen başlıca etken nedir?', 'Üst troposferdeki havanın nem miktarı', ['Uçağın yolcu sayısı', 'Yerdeki rüzgâr yönü', 'Günün saati, Ay\'ın evresi ve uçağın hızı'], 'Üst seviyedeki hava buza göre doymuşsa iz kristalleri buharlaşmaz, hatta büyüyerek sirrusa benzer bir örtüye dönüşür; kuru havada iz hızla kaybolur.'),
  ('Çok güçlü orman yangınlarının bazen kendi gök gürültülü fırtınasını (pirokümülonimbus) oluşturması itfaiyeciler açısından neden tehlikelidir?', 'Bulutun aşağı akımları ve yıldırımları yangını öngörülemez biçimde yayabilir', ['Bulutun bıraktığı yoğun yağışın yangını her durumda tamamen söndürmesi', 'Bulut duman yoğunluğunu sıfıra indirir', 'Bulut yalnızca yangının sıcaklığını düşürür'], 'Pirokümülonimbusların yaydığı kuvvetli, yön değiştiren rüzgârlar ve yağışsız yıldırımlar yangını hızla genişletebilir ve yeni yangınlar başlatabilir.'),
  ('Tipik bir bulut damlacığının çapı yaklaşık 0,02 mm, tipik bir yağmur damlasının çapı ise yaklaşık 2 mm\'dir. Bir yağmur damlasını oluşturmak için yaklaşık kaç bulut damlacığı gerekir?', '1 000 000', ['100', '10 000', '100 000 000'], 'Çaplar oranı 2 / 0,02 = 100\'dür; hacim çapın küpüyle orantılı olduğundan 100³ = 1 000 000 damlacık gerekir.'),
  ('Çapı yaklaşık 5 mm\'yi aşan yağmur damlalarının neden çok seyrek görüldüğü en iyi nasıl açıklanır?', 'Bu boyutta damlalar düşerken kararsızlaşıp küçük damlalara bölünür', ['Bu boyutta damlalar hemen buza dönüşür', 'Bu kadar büyük bir damla bulutun içinde hiçbir koşulda oluşamaz', 'Büyük damlalar havada asılı kalıp düşmez'], 'Damla büyüdükçe hava direnci onu yassılaştırır ve ortası çökerek paraşüt gibi açılır; sonunda yüzey gerilimi yetmez ve damla parçalanır.'),
  ('Orta enlemlerde yaz aylarında yere yağmur olarak ulaşan yağışın önemli bir kısmı bulutta hangi hâlde başlar?', 'Kar ya da buz kristali olarak', ['Doğrudan büyük sıvı damlalar olarak', 'Yerden yükselen su sıçramaları olarak', 'Dolu taneleri olarak ve hiç erimeden'], 'Bu bölgelerdeki bulutların üst kısmı donma düzeyinin üstündedir; yağış buz evresinde başlar ve ılık katmanlardan geçerken eriyip yağmura dönüşür.'),
  ('Kar kristallerini laboratuvarda ilk kez yapay olarak üreten ve \'kar kristalleri gökten gönderilmiş mektuplardır\' sözüyle tanınan Japon fizikçi kimdir?', 'Ukichiro Nakaya', ['Hideki Yukawa', 'Fusakichi Omori', 'Kiyoo Wadati'], 'Nakaya 1930\'larda kristalleri tavşan kılı üzerinde büyüterek biçimlerin sıcaklık ve neme göre nasıl değiştiğini gösteren diyagramını hazırladı.'),
  ('1885\'te bir kar kristalinin ilk mikroskop fotoğrafını çeken ve ömrü boyunca binlerce kristal fotoğraflayan Vermont\'lu çiftçi kimdir?', 'Wilson Bentley', ['Luke Howard', 'Robert FitzRoy', 'William Ferrel'], '\'Kar Tanesi Bentley\' diye anılan Wilson Bentley, mikroskobu bir körüklü kameraya bağlayarak kar kristallerini fotoğraflamayı başardı.'),
  ('Yaygın bir yaklaşıma göre taze karın eridiğinde verdiği su, kar kalınlığının yaklaşık onda biridir. Bir gecede 25 cm kar yağdığına göre bu karın su eşdeğeri yaklaşık kaç milimetredir?', '25 mm', ['2,5 mm', '250 mm', '10 mm'], '25 cm = 250 mm kar; onda biri 25 mm su eder. Islak karda bu oran yükselir, çok kuru toz karda düşer.'),
  ('Yer seviyesindeki hava sıcaklığı +2 °C olduğu hâlde bazen yağmur yerine kar yağdığı görülür. Bunun için en olası koşul hangisidir?', 'Havanın kuru olması ve buharlaşmanın kar tanelerini soğutması', ['Havanın çok nemli olup sisle kaplı bulunması', 'Basıncın çok düşük olup kar tanelerini sıkıştırarak donmuş tutması', 'Rüzgârın hiç esmemesi ve havanın tamamen durgun olması'], 'Kuru havada kar tanelerinin yüzeyi buharlaşırken ısı çeker; bu soğuma erimeyi geciktirir, bu yüzden ıslak termometre sıcaklığı yağış türünü kuru sıcaklıktan daha iyi belirler.'),
  ('Çok soğuk ve açık havalarda, bulut olmadığı hâlde havada süzülen ve güneşte ışıldayan çok küçük buz kristallerine ne ad verilir?', 'Elmas tozu', ['Kırç', 'Kar topağı', 'Kırağı'], 'Elmas tozu genellikle kutup bölgelerinde, çok düşük sıcaklıklarda doğrudan açık havada oluşan buz iğneleri ve levhacıklarıdır; güneş sütunu gibi optik olaylara yol açabilir.'),
  ('Dolunun tropik bölgelerde yere ulaşma sıklığının, çok güçlü fırtınalara rağmen orta enlemlerden daha az olmasının nedeni nedir?', 'Donma düzeyi yüksekte olduğundan taneler düşerken erir', ['Tropiklerde bulutlarda hiç buz oluşmaz', 'Tropiklerde fırtınalar yalnız gece görülür', 'Tropik bulutlar dolu üretemeyecek kadar alçak ve incedir'], 'Tropiklerde 0 °C düzeyi 4–5 km yükseklikte olduğundan dolu taneleri yere ulaşmadan uzun bir ılık katmandan geçer ve küçük taneler büyük ölçüde erir.'),
  ('Bulut tohumlamanın her bulutta yağış üretememesinin temel nedeni aşağıdakilerden hangisidir?', 'Yalnızca zaten uygun nem ve sıcaklıktaki bulutlarda işe yarayabilir', ['Tohumlama maddeleri havada hemen yok olur', 'Tohumlama yalnızca açık gökyüzünde uygulanabilir', 'Tohumlama bulutları her zaman dağıtır'], 'Tohumlama yeni su yaratmaz; yalnızca var olan aşırı soğumuş damlacıkların ya da nemin yağışa dönüşme sürecini kolaylaştırabilir.'),
  ('Denizcilik ve havacılıkta kullanılan 1 knot, saatte 1 deniz mili (1,852 km) demektir. 30 knotluk bir rüzgârın hızı yaklaşık kaç km/sa\'tir?', '56 km/sa', ['30 km/sa', '48 km/sa', '62 km/sa'], '30 × 1,852 = 55,56 km/sa, yani yaklaşık 56 km/sa.'),
  ('Dünya Meteoroloji Örgütü\'nün standartlarına göre yüzey rüzgârı, açık arazide yerden kaç metre yükseklikte ölçülmelidir?', '10 m', ['2 m', '50 m', '100 m'], 'Rüzgâr yere yaklaştıkça sürtünmeyle yavaşladığından karşılaştırılabilir ölçümler için anemometreler genellikle 10 m yüksekliğe yerleştirilir.'),
  ('Üç hücreli genel dolaşım modelinde yaklaşık 30° ile 60° enlemler arasında bulunan, yüzeyde batı rüzgârlarını oluşturan dolaşım hücresinin adı nedir?', 'Ferrel hücresi', ['Walker hücresi', 'Kutup hücresi', 'Rossby hücresi'], 'Ferrel hücresi Hadley ve kutup hücreleri arasında kalır; yüzeyde havayı kutba doğru taşır ve Coriolis etkisiyle batı rüzgârları oluşur.'),
  ('Ekvator çevresinde rüzgârların buluşup yükseldiği, bol yağışlı Tropikal Kuşak Yakınsama Bölgesi (ITCZ) yıl içinde nasıl hareket eder?', 'Güneş ışınlarının dik geldiği bölgeyi izleyerek kuzeye ve güneye kayar', ['Yıl boyu tam ekvator üzerinde sabit kalır', 'Her yıl düzenli olarak batıdan doğuya dünyayı dolaşır', 'Yalnızca kutup bölgelerinde ortaya çıkar'], 'ITCZ temmuzda Kuzey Yarımküre\'ye, ocakta güneye doğru kayar; bu hareket tropik bölgelerde yağışlı ve kurak mevsimlerin oluşmasını sağlar.'),
  ('Afrika\'da Sahra\'nın hemen güneyindeki Sahel kuşağında yağışların yalnızca yazın birkaç ay boyunca düşmesi en iyi hangi olguyla açıklanır?', 'ITCZ\'nin yazın bu kuşağa kadar kuzeye kayması', ['Sahra\'dan esen soğuk kutup rüzgârlarının yazın durması', 'Kış aylarında Atlas Dağları\'nın yağışı engellemesi', 'Yaz aylarında okyanus akıntılarının tersine dönmesi'], 'Yazın yağışlı yakınsama kuşağı Sahel\'e ulaşır; kışın güneye çekildiğinde bölge kuru kuzeydoğu rüzgârlarının etkisinde kalır.'),
  ('Yaklaşık 60° enlemler çevresinde, ılık batı rüzgârları ile soğuk kutup havasının karşılaştığı ve sık sık fırtınalı alçak basınçların oluştuğu sınır kuşağına ne ad verilir?', 'Kutup cephesi', ['At enlemleri', 'Ekvatoral durgunluk', 'Dönence kuşağı'], 'Kutup cephesi boyunca keskin sıcaklık farkları bulunur; orta enlem siklonlarının çoğu bu kuşaktaki dalgalanmalardan doğar.'),
  ('Kutup jet akımının kışın yazdan daha güçlü olmasının nedeni nedir?', 'Kışın kutuplarla tropikler arasındaki sıcaklık farkı daha büyüktür', ['Kışın Dünya Güneş\'e daha uzaktır', 'Kışın havada daha az su buharı bulunur ve hava hafifler', 'Kışın Dünya\'nın dönüş hızı artar'], 'Jet akımının hızı, iki hava kütlesi arasındaki sıcaklık (dolayısıyla basınç) farkıyla ilişkilidir; kışın kutuplar çok soğuduğundan bu fark ve jet güçlenir.'),
  ('Üst seviye hava haritalarında \'oluk\' (trof) ve \'sırt\' terimleri genellikle hangi hava koşullarıyla ilişkilendirilir?', 'Oluk soğuk ve kararsız, sırt ılık ve açık havayla', ['Oluk sıcak ve kurak, sırt soğuk ve yağışlı havayla', 'İkisi de yalnızca sisli ve rüzgârsız havayla', 'Oluk kar, sırt ise yalnızca dolu yağışıyla'], 'Oluk bölgesinde soğuk hava güneye sarkar ve yükselişi destekler; sırtta ılık hava kuzeye uzanır ve çökme hareketi açık hava getirir.'),
  ('Yaklaşık 60° enlemler çevresinde, yüzeyde ortalama olarak alçak basınç kuşağı bulunmasının nedeni nedir?', 'Farklı hava kütlelerinin karşılaşıp havanın yükselmesi', ['Bu enlemlerde havanın sürekli alçalması', 'Bu kuşakta Güneş ışınlarının en dik gelmesi', 'Okyanusların bu enlemde tamamen donması'], 'Ferrel hücresinin kutba giden ılık havası ile kutup hücresinin soğuk havası burada buluşur; ılık hava yükselir ve subpolar alçak basınç kuşağı oluşur.'),
  ('Hırvatistan ve Slovenya\'nın Adriyatik kıyılarında, özellikle Trieste çevresinde kışın kuzeydoğudan dağlardan aşağı çok sert hamlelerle inen soğuk rüzgâra ne ad verilir?', 'Bora', ['Sirocco', 'Chinook', 'Hamsin'], 'Bora, iç kesimlerde biriken soğuk havanın Dinar Alpleri\'nden kıyıya doğru dökülmesiyle oluşan katabatik bir rüzgârdır.'),
  ('Kuzey Amerika\'da Kayalık Dağlar\'ın doğu eteklerine inen ve kışın birkaç saat içinde sıcaklığı onlarca derece artırıp karı hızla eriten sıcak, kuru rüzgâr hangisidir?', 'Chinook', ['Mistral', 'Bora', 'Harmattan'], 'Chinook bir fön rüzgârıdır; yerel halk karı eritme gücü nedeniyle ona \'kar yiyen\' der.'),
  ('Güney Kaliforniya\'da özellikle sonbaharda iç bölgelerden kıyıya doğru esen, çok kuru ve sıcak \'Santa Ana\' rüzgârları neden korkulan bir olaydır?', 'Orman yangınlarını hızla büyütürler', ['Kıyılarda yoğun sis oluştururlar', 'Kar fırtınalarına yol açarlar', 'Deniz suyunu dondururlar'], 'Santa Ana rüzgârları alçalırken ısınıp kurur; düşük nem ve kuvvetli hamleler bitki örtüsünü kurutup yangınların hızla yayılmasına neden olur.'),
  ('Kasımdan marta kadar Sahra\'dan Batı Afrika\'ya ve Gine Körfezi kıyılarına doğru esen, havayı tozla bulanıklaştıran kuru kuzeydoğu rüzgârı hangisidir?', 'Harmattan', ['Mistral', 'Chinook', 'Bora'], 'Harmattan nemin çok düştüğü, havanın puslu ve tozlu olduğu kurak mevsimi getirir; bazen görüşü birkaç yüz metreye indirir.'),
  ('Mısır\'da ilkbaharda çölden esen sıcak ve tozlu rüzgâra verilen, Arapçada \'elli\' anlamına gelen ve Türkçede de kullanılan ad hangisidir?', 'Hamsin', ['Samyeli', 'Sirocco', 'Bora'], 'Hamsin (khamsin) adını, rüzgârın yılda yaklaşık elli günlük bir dönemde görüldüğü inancından alır.'),
  ('Bora gibi katabatik rüzgârlar dağdan inerken ısınmalarına karşın kıyıya hâlâ soğuk ulaşır. Bunun nedeni nedir?', 'Kaynak bölgedeki hava başlangıçta çok soğuk olduğu için ısınma yetmez', ['Bu rüzgârlar inerken hiç ısınmaz, aksine soğur', 'Dağdan inen hava denizden ısı alamaz ve donar', 'Yerçekimi havanın sıcaklığını sabit tutar'], 'Hava alçalırken sıkışıp ısınır; ancak yaylada çok soğumuş havanın başlangıç sıcaklığı o kadar düşüktür ki kıyıya ulaştığında bile çevresinden soğuktur.'),
  ('Atlas Okyanusu\'nda yaklaşık 30–40° kuzey enlemlerinde bulunan ve yazın Batı Avrupa ile Akdeniz\'e kuru, açık hava taşıyan sürekli yüksek basınç alanına ne ad verilir?', 'Azor yüksek basıncı', ['İzlanda alçak basıncı', 'Sibirya yüksek basıncı', 'Basra alçak basıncı'], 'Azor (Bermuda) yüksek basıncı subtropikal yüksek basınç kuşağının bir parçasıdır; yazın kuzeye genişleyerek Akdeniz yazlarının kuraklığına katkıda bulunur.'),
  ('Yazın Basra Körfezi ve çevresinde aşırı ısınan karanın üzerinde oluşan, Türkiye\'nin güneydoğusuna sıcak ve kuru hava getiren basınç alanının türü hangisidir?', 'Isıl (termik) alçak basınç', ['Dinamik yüksek basınç', 'Kutup yüksek basıncı', 'Cephesel alçak basınç'], 'Basra alçak basıncı, yerin güçlü ısınmasıyla yükselen havadan doğan ısıl bir alçak basınçtır; yağış getirmez çünkü hava çok kurudur.'),
  ('Kışın Doğu Akdeniz\'de oluşup Türkiye\'nin güney kıyılarına ve Orta Doğu\'ya kış yağışlarının önemli bir bölümünü getiren alçak basınç sistemleri hangi adla bilinir?', 'Kıbrıs alçak basınçları', ['Basra alçak basınçları', 'Azor yüksek basınçları', 'Sibirya alçak basınçları'], 'Kıbrıs çevresinde ılık deniz üzerinde gelişen bu siklonlar Akdeniz kıyılarına ve Güneydoğu Anadolu\'ya kış yağışı taşır.'),
  ('Sahra çölü üzerinde oluşan ve Akdeniz\'e ulaştığında aşırı sıcak, kuru ve tozlu hava getiren hava kütlesi hangi simgeyle gösterilir?', 'cT', ['mP', 'cP', 'mT'], 'Karasal tropikal (cT) hava kütleleri sıcak çöllerde oluşur; çok sıcak ve kurudur.'),
  ('Orta enlem siklonları ile tropikal siklonlar karşılaştırıldığında enerji kaynakları açısından temel fark nedir?', 'Orta enlem siklonu hava kütleleri arasındaki sıcaklık farkından, tropikal siklon gizli ısıdan beslenir', ['İkisi de yalnızca okyanus akıntılarından enerji alır', 'Orta enlem siklonları yalnız gizli ısıyla, tropikal siklonlar cephelerle beslenir', 'İkisinin de enerjisi doğrudan yerin ısısından gelir'], 'Orta enlem siklonları cepheli, soğuk çekirdekli sistemlerdir; tropikal siklonlar cephesiz ve sıcak çekirdeklidir.'),
  ('Hava haritasında üçgen ve yarım dairelerin aynı tarafta, birbirini izleyerek dizildiği mor çizgi neyi gösterir?', 'Kapalı (oklüzyon) cepheyi', ['Durgun cepheyi', 'Sıcak cepheyi', 'Fırtına (kararsızlık) hattını'], 'Kapalı cephe hem soğuk hem sıcak cephenin özelliklerini taşıdığı için iki simge birlikte, mor renkle çizilir.'),
  ('Hava haritasında kırmızı yarım dairelerle mavi üçgenlerin çizginin zıt yanlarına sırayla yerleştirildiği cephe hangisidir ve neyi anlatır?', 'Durgun cephe; hava kütleleri birbirini itmez', ['Kapalı cephe; iki soğuk hava kütlesi birleşir', 'Sıcak cephe; sıcak hava çok hızlı ilerler', 'Kuru hat; nem farkı yoktur'], 'Durgun cephede simgeler karşılıklı bakar çünkü iki hava kütlesinden hiçbiri belirgin biçimde ilerlemez.'),
  ('Bir istasyonda bir cephenin geçtiği saatlerde çiğ noktasının birden 6 °C\'den 15 °C\'ye yükseldiği ve sıcaklığın arttığı görülüyor. En olası açıklama hangisidir?', 'Bir sıcak cephe geçmiş ve istasyon ılık, nemli havaya girmiştir', ['Bir soğuk cephe geçmiş ve kuru kutup havası gelmiştir', 'Bölgeye çöl kökenli kuru bir hava kütlesi girmiştir', 'Yüksek basınç merkezi istasyonun tam üstüne yerleşmiş ve hava çökmeye başlamıştır'], 'Sıcak cephenin arkasında sıcak sektörün ılık ve nemli havası bulunur; hem sıcaklık hem çiğ noktası yükselir.'),
  ('Bir soğuk cephenin birkaç on kilometre önünde oluşan, ardı ardına dizilmiş gök gürültülü fırtınalardan oluşan uzun kuşağa ne ad verilir?', 'Fırtına hattı', ['Yağış gölgesi', 'Kutup girdabı', 'Sıcak sektör'], 'Fırtına (kararsızlık) hatları yüzlerce kilometre boyunca uzanabilir; geçerken kuvvetli hamleler, sağanak ve bazen dolu getirir.'),
  ('Uydu görüntülerinde bir kümülonimbusun örsünün üzerinde kubbe gibi taşan bölüme (aşırı yükselen tepe) rastlanması ne anlama gelir?', 'Fırtınanın çok güçlü bir yükselici akıma sahip olduğu', ['Fırtınanın dağılmak üzere olduğu', 'Bulutun yalnızca sıvı damlacıklardan oluştuğu', 'Fırtınanın bir sıcak cepheye dönüştüğü ve yağışın sona ermek üzere olduğu'], 'Yükselici akım o kadar güçlüdür ki hava, kazandığı ivmeyle tropopozun üzerine taşar; bu, dolu ve şiddetli rüzgâr riskinin yüksek olduğunu gösterir.'),
  ('Hava radarında bir süper hücrenin güneybatı köşesinde görülen \'kanca yankısı\' meteorologlar için neyin işaretidir?', 'Fırtınanın dönen bir mezosiklon barındırdığı ve hortum riskinin arttığı', ['Fırtınanın yalnızca kar ürettiği', 'Radar anteninin arızalandığı', 'Fırtınanın bir sıcak cepheyle birleşip zayıflamaya başladığı ve dağılacağı'], 'Mezosiklonun yağışı kendi çevresine sarması radarda kanca biçimli bir yankı oluşturur; bu desen hortum uyarılarında önemli bir ipucudur.'),
  ('Bir fırtına bulutundan inen soğuk havanın yere çarpıp her yöne yayıldığı, çapı 4 km\'den küçük ve çok kısa süreli kuvvetli rüzgâr olayına ne ad verilir?', 'Mikropatlama', ['Hortum', 'Fön', 'Hale'], 'Mikropatlamalar özellikle iniş ve kalkıştaki uçaklar için tehlikelidir; uçak önce karşıdan sonra arkadan rüzgâr alarak hızla taşıma kuvvetini yitirebilir.'),
  ('Yüzlerce kilometre boyunca ilerleyen bir fırtına sisteminin yol açtığı, geniş alanda ve düz çizgiler hâlinde esen yıkıcı rüzgârlara ne ad verilir?', 'Derecho', ['Tayfun', 'Bora', 'Haboob'], 'İspanyolca \'düz\' anlamına gelen derecho, dönen hortum rüzgârlarından farklı olarak düz çizgiler boyunca kuvvetli hasar bırakır.'),
  ('Buluttan yere inen bir yıldırımda gözle görülen asıl parlak ışık hangi aşamada oluşur?', 'Dönüş vuruşu', ['Basamaklı öncü', 'Yük ayrışması', 'Korona boşalması'], 'Önce sönük, basamak basamak ilerleyen bir öncü yol açar; yerden yükselen bir akımla birleşince kanal boyunca çok güçlü dönüş vuruşu oluşur ve asıl ışık budur.'),
  ('Bir yıldırımın gözümüze titreşerek ya da kesik kesik yanıp sönerek görünmesinin nedeni nedir?', 'Aynı kanaldan art arda birkaç vuruş geçer', ['Gözümüz yıldırımın ışığını iki kez algılar', 'Yıldırım havada yavaşça zikzak çizerek düşer', 'Bulutlar yıldırımın ışığını aralıklarla engeller'], 'Bir yıldırım çakması genellikle üç-dört, bazen daha fazla vuruştan oluşur; vuruşlar arasındaki on milisaniyelik aralıklar titreşim izlenimi verir.'),
  ('Tipik bir yıldırım vuruşunda akan elektrik akımı yaklaşık hangi büyüklüktedir?', 'On binlerce amper', ['Birkaç miliamper', 'Birkaç amper', 'Birkaç milyar amper'], 'Tipik bir dönüş vuruşunda akım 20–30 kA civarındadır; bazı güçlü vuruşlar 100 kA\'yı aşabilir.'),
  ('Fırtına bulutunun örsünden kaynaklanan \'pozitif yıldırımlar\' neden özellikle tehlikeli kabul edilir?', 'Daha güçlü akım taşır ve fırtınadan uzakta açık gökyüzüne düşebilir', ['Yalnızca su yüzeyine düşer ve büyük dalga oluşturur', 'Ses çıkarmadığı için hiç fark edilmez, ancak akımı çok zayıf olduğundan zararsızdır', 'Yalnızca gece görüldüğü için yangın başlatamaz'], 'Pozitif yıldırımlar seyrektir ama daha uzun süreli ve güçlüdür; fırtınanın kilometrelerce ötesinde \'mavi gökten yıldırım\' olarak düşebilirler.'),
  ('Venezuela\'da Maracaibo Gölü\'nün Catatumbo Nehri\'ne döküldüğü bölge hangi olayla ünlüdür?', 'Yılın birçok gecesinde saatlerce süren yıldırım fırtınaları', ['Her yıl aynı gün görülen tam güneş tutulmaları', 'Dünyanın en sık görülen kar fırtınaları ve yılın yarısını kaplayan buz örtüsü', 'Yılda birkaç kez donan tropik gölü'], '\'Catatumbo şimşeği\' denen olayda dağlarla çevrili sıcak ve nemli göl üzerinde gece boyunca neredeyse sürekli şimşek çakar.'),
  ('Yıldırım konum belirleme ağları, ışığı görmeden de bir yıldırımın nereye düştüğünü nasıl saptar?', 'Yıldırımın yaydığı radyo dalgalarını birkaç istasyonda farklı zamanlarda algılayarak', ['Gök gürültüsünü uydudan dinleyerek', 'Gök gürültüsünü uydudaki duyarlı mikrofonlarla dinleyip sesin yönünü bularak', 'Bulutun ağırlığını tartarak'], 'Her boşalma geniş bantlı radyo atımları yayar; atımın farklı alıcılara varış zamanı farkları kullanılarak çakmanın konumu üçgenleme ile bulunur.'),
  ('Açık arazide yıldırım riski varken ayakları bitiştirerek çömelmenin önerilmesinin elektriksel gerekçesi nedir?', 'Yere yayılan akımın iki ayak arasında oluşturacağı gerilim farkını azaltmak', ['Bedeni yerden tamamen yalıtıp akımın vücuttan hiçbir biçimde geçmemesini sağlamak', 'Vücudun elektrik yükünü havaya boşaltmak', 'Yıldırımın sesinden kulakları korumak'], 'Yıldırım yere düşünce akım topraktan halka hâlinde yayılır; ayaklar açıkken iki ayak arasında büyük bir gerilim farkı (adım gerilimi) oluşabilir.'),
  ('Bir tropikal siklon, sürekli rüzgâr hızı saatte yaklaşık 63 km\'yi aştığında hangi aşamaya geçer ve genellikle bu aşamada ad alır?', 'Tropikal fırtına', ['Tropikal depresyon', 'Tropikal dalga', 'Ekstratropikal siklon'], 'Tropikal depresyon 63 km/sa\'in altındadır; tropikal fırtına aşamasında sisteme listeden bir ad verilir. 119 km/sa üzerinde kasırga (hurricane, tayfun) sayılır.'),
  ('Özel uçaklarla kasırgaların içine girip ölçüm yapan \'kasırga avcıları\' fırtınanın içine bıraktıkları paraşütlü algılayıcılarla ne elde eder?', 'Fırtınanın içinden yere kadar sıcaklık, nem, basınç ve rüzgâr profilini', ['Fırtınanın uzaydan çekilmiş yüksek çözünürlüklü fotoğraflarını ve yıldırım haritasını', 'Deniz dibinin derinlik haritasını', 'Fırtınadaki yıldırımların renklerini'], 'Bırakılan algılayıcılara dropsonde denir; düşerken saniyede bir ölçüm göndererek uyduların göremediği iç yapıyı ortaya çıkarır.'),
  ('2013\'te Filipinler\'de Tacloban kentini fırtına kabarmasıyla büyük ölçüde yıkan, kayıtlara geçmiş en güçlü karaya çıkışlardan birini yapan tayfun hangisidir?', 'Haiyan', ['Bhola', 'Katrina', 'Sandy'], 'Filipinler\'de Yolanda adıyla da bilinen Haiyan, binlerce kişinin ölümüne ve milyonlarca kişinin evsiz kalmasına yol açtı.'),
  ('1900 yılında Teksas\'ta bir ada kentini yerle bir eden ve ABD tarihinin en ölümcül doğal afeti olarak anılan kasırga hangi kentin adıyla bilinir?', 'Galveston', ['Miami', 'New Orleans', 'Houston'], 'Galveston kasırgasında binlerce kişi öldü; ardından kent yükseltilip deniz duvarı inşa edildi.'),
  ('Çok soğuk bir sonbahar sabahında ılık bir gölün üzerinden buhar tütüyormuş gibi yükselen sise ne ad verilir ve nasıl oluşur?', 'Buharlaşma sisi; ılık sudan buharlaşan nem soğuk havada hemen yoğuşur', ['Radyasyon sisi; göl suyu gece ışınımla donar', 'Adveksiyon sisi; soğuk deniz havası karaya taşınır', 'Yamaç sisi; hava dağ yamacında yükselip soğur'], 'Soğuk hava ılık su yüzeyinden gelen buharı taşıyamaz; buhar hemen yoğuşarak duman gibi görünen sis tutamları oluşturur. Denizlerde buna deniz dumanı da denir.'),
  ('Şili\'deki Atacama Çölü\'nün kıyı kesimlerinde bazı köylerde içme ve sulama suyu elde etmek için büyük ağlar kurulur. Bu ağlar hangi kaynaktan su toplar?', 'Rüzgârla taşınan sis damlacıklarından', ['Yeraltından kılcallıkla yükselen sudan', 'Gece yağan kardan', 'Deniz suyunun buharlaşmasından doğrudan'], 'Okyanustan gelen sis ağların ince liflerine çarpar; damlacıklar birleşip aşağıdaki oluklara süzülür. Yağışın neredeyse hiç olmadığı bölgede bu önemli bir su kaynağıdır.'),
  ('Çok düşük sıcaklıklarda, örneğin −30 °C\'nin altında, kentlerde araç egzozlarından ve bacalardan çıkan buharla oluşan, buz kristallerinden yapılmış sise ne ad verilir?', 'Buz sisi', ['Kırağı sisi', 'Kuru pus', 'Duman-sis'], 'Bu kadar soğuk havada su buharı doğrudan küçük buz kristallerine dönüşür; Sibirya ve Alaska kentlerinde sık görülür.'),
  ('Karla kaplı bir arazide kapalı ve yaygın bulut örtüsü altında ufuk çizgisinin ve yerdeki girinti-çıkıntıların ayırt edilemez hâle gelmesine ne ad verilir?', 'Beyaz karanlık', ['Kutup gecesi', 'Alacakaranlık', 'Kar körlüğü sendromu'], 'Bulutlar ve kar ışığı defalarca yansıtıp her yönden eşit dağıttığı için gölgeler kaybolur; gök ve yer aynı beyazlıkta görünür ve yön bulmak zorlaşır.'),
  ('Londra\'da yaptığı ölçümlerle kent merkezinin çevresindeki kırsal alandan daha sıcak olduğunu 19. yüzyılın başında ilk kez belgeleyen kişi kimdir?', 'Luke Howard', ['John Dalton', 'Robert FitzRoy', 'Francis Galton'], 'Howard, \'Londra\'nın İklimi\' adlı eserinde kentin özellikle geceleri çevresinden daha ılık olduğunu kayda geçirdi; bu, kentsel ısı adasının ilk tanımı sayılır.'),
  ('Birincil gökkuşağı, gözlemcinin gölgesinin başının bulunduğu noktadan (Güneş\'in tam karşısındaki nokta) yaklaşık 42° uzaklıkta bir çember yayı olarak görülür. Buna göre Güneş ufkun 50° üzerindeyken yerdeki bir gözlemci gökkuşağını neden göremez?', 'Yayın tamamı ufkun altında kalır', ['Işık yağmur damlalarında hiç kırılmaz', 'Güneş çok yüksekteyken yağmur yağamaz', 'Gökkuşağı yalnız öğle saatinde oluşur'], 'Karşı nokta ufkun 50° altındadır; 42° yarıçaplı çemberin en üst noktası bile ufkun 8° altında kalır. Bu yüzden gökkuşakları sabah ve akşamüstü görülür.'),
  ('Uçaktan aşağıdaki yağmur bulutlarına bakan bir yolcu bazen gökkuşağını tam bir çember olarak görebilir. Yerden çoğunlukla yalnızca yay görülmesinin nedeni nedir?', 'Yer, çemberin alt kısmının oluşacağı yağmur damlalarını keser', ['Yere yakın havanın yoğunluğu ışığın damlalarda kırılmasını tamamen engeller', 'Gökkuşağı yalnızca bulutların üstünde oluşur', 'Yerdeki gözlemcinin gözü çemberi göremez'], 'Gökkuşağı karşı nokta çevresinde bir çemberdir; yerde bu çemberin alt kısmı ufkun altına düştüğünden yalnız üst yay görünür.'),
  ('İnce bulutların arkasındaki Ay\'ın hemen çevresinde, içi mavimsi dışı kırmızımsı küçük renkli halkalar görülüyor. 22°\'lik haleden çok daha küçük olan bu halkalar (taç) hangi olayla oluşur?', 'Küçük bulut damlacıklarında kırınım', ['Buz kristallerinde kırılma', 'Ay yüzeyindeki kraterlerin yansıması', 'Ay\'ın kendi atmosferinin parlaması'], 'Taç (korona) birkaç derece genişliğindedir ve damlacık boyutuna bağlıdır; damlacıklar küçüldükçe halkalar büyür.'),
  ('Karlı dağ zirvelerinin gün batımından hemen sonra Güneş ufkun altına indiği hâlde pembe-kızıl renkte parladığı görülür. Bu olaya ne ad verilir?', 'Alpenglow (dağ kızıllığı)', ['Brocken hayaleti', 'Elmas tozu', 'Güneş köpeği (parhelion)'], 'Güneş vadiden görünmez olduğunda bile yüksek zirveler ufkun ötesinden gelen ya da atmosferde saçılan kızıl ışıkla aydınlanır.'),
  ('Hareketli parçası bulunmayan ultrasonik anemometreler rüzgâr hızını nasıl ölçer?', 'Ses atımlarının iki algılayıcı arasındaki yolculuk süresindeki farktan', ['Rüzgârın döndürdüğü kapların devir sayısından', 'Isınan bir telin soğuma hızından', 'Rüzgârla eğilen esnek bir çubuğun açısından ve titreşim sıklığından'], 'Ses rüzgâr yönünde daha hızlı, rüzgâra karşı daha yavaş yol alır; farklı doğrultulardaki süre farklarından hem hız hem yön hesaplanır.'),
  ('Otomatik yağış ölçerlerde kullanılan \'devrilen kova\' düzeneği nasıl çalışır?', 'Belirli miktarda su dolan küçük kova devrilir ve her devrilme sayılır', ['Yağmur damlalarının kovaya çarparken çıkardığı ses duyarlı bir mikrofonla sayılır', 'Toplanan su her saat tartılıp boşaltılır', 'Damlalar bir lazer perdesinden geçerken boyları ölçülür'], 'Her devrilme genellikle 0,2 mm yağışa karşılık gelir; devrilme sayısı ve zamanı yağış miktarını ve şiddetini verir.'),
  ('Buharlaşma miktarını ölçmek için açık alana yerleştirilen, içindeki suyun her gün ne kadar azaldığı ölçülen geniş, sığ kaba ne ad verilir?', 'Buharlaşma kabı (tavası)', ['Yağış ölçer', 'Kar yastığı (kar ağırlığı ölçer)', 'Barograf tamburu'], 'Kaptaki su düzeyindeki azalma, yağış olduysa düzeltilerek günlük buharlaşmayı verir; sulama planlamasında kullanılır.'),
  ('Günümüzde meteoroloji gözlemlerinin büyük kısmının insan gözlemci yerine otomatik istasyonlarla yapılmasının en önemli yararı hangisidir?', 'Uzak yerlerde bile sık ve sürekli veri elde edilmesi', ['Bulut türlerinin ve renklerinin her koşulda insan gözünden daha iyi tanınması', 'Ölçümlerin hiç bakım gerektirmemesi', 'Yıldırımın istasyonlara hiç zarar verememesi'], 'Otomatik istasyonlar dakikalık veri gönderebilir; ancak bulut türü gibi bazı gözlemler hâlâ insan gözüyle daha iyi yapılır.'),
  ('Bir öğrenci evinin balkonundaki dijital termometrenin, meteoroloji istasyonunun aynı saatteki değerinden her öğleden sonra 4–5 °C yüksek gösterdiğini fark ediyor. En olası açıklama hangisidir?', 'Termometre doğrudan güneş alan ya da duvardan ısı alan bir yerdedir', ['Meteoroloji istasyonlarının sıcaklığı yasal olarak her zaman biraz düşük göstermesi', 'Balkonlarda hava basıncı daha düşüktür', 'Dijital termometreler yalnız gece doğru ölçer'], 'Güneşte kalan ya da ısınan duvara yakın bir termometre havanın değil kendi gövdesinin ve çevresinin sıcaklığını ölçer; doğru ölçüm gölgede ve havalandırmalı yerde yapılır.'),
  ('Dünya genelindeki meteoroloji istasyonlarının sinoptik gözlemlerini aynı anda, örneğin 00, 06, 12 ve 18\'de yapmasının ve saatleri UTC ile belirtmesinin amacı nedir?', 'Aynı ana ait verilerle tek bir hava haritası çizebilmek', ['Gözlemcilerin gece uyuyabilmesini sağlamak', 'Her ülkenin kendi yerel saatini koruyup verileri yalnızca kendi içinde kullanması', 'Uyduların istasyonları rahatça fotoğraflayabilmesi'], 'Sinoptik (\'bir arada görme\') yaklaşımı, geniş bir alandaki havanın aynı andaki durumunun haritalanmasına dayanır; bu yüzden tek bir zaman ölçeği kullanılır.'),
  ('Havalimanlarında düzenli aralıklarla yayımlanan, rüzgâr, görüş, bulut, sıcaklık ve basıncı kısaltmalarla bildiren rutin havacılık hava raporuna ne ad verilir?', 'METAR', ['TAF', 'SYNOP', 'NOTAM'], 'METAR bir gözlem raporudur; TAF ise aynı havalimanı için önümüzdeki saatlere ait tahmindir.'),
  ('Bir METAR raporunda rüzgâr bilgisi \'27015KT\' olarak verilmiştir. Bu ne anlama gelir?', 'Rüzgâr batıdan 15 knot hızla esiyor', ['Rüzgâr 27 knot hızla güneyden esiyor', 'Rüzgâr doğudan 15 km/sa hızla esiyor', 'Rüzgâr 270 km/sa hızla 15° yönünden esiyor'], 'İlk üç rakam rüzgârın geldiği yönü derece olarak (270° = batı), sonraki iki rakam hızı, KT ise birimin knot olduğunu belirtir.'),
  ('Bir METAR raporunda \'BKN015\' ifadesi yer alıyor. Bu ifade gökyüzü hakkında ne söyler?', 'Yaklaşık 1500 ft\'te gökyüzünün 5–7 oktasını kaplayan bir bulut katmanı vardır', ['Bulut tabanı 15 metrede ve gökyüzü tamamen açıktır', 'Gökyüzünün 1–2 oktası 150 ft\'te bulutludur', 'Görüş uzaklığı 15 km\'dir'], 'BKN (broken) parçalı kapalı, yani 5–7 okta anlamına gelir; ardından gelen üç rakam taban yüksekliğini yüz feet cinsinden verir (015 = 1500 ft).'),
  ('Havacılık raporlarında yer alan \'CAVOK\' ifadesi neyi bildirir?', 'Görüş, bulut ve hava koşullarının uçuş için iyi olduğunu', ['Kuvvetli yan rüzgâr nedeniyle pistin geçici olarak trafiğe kapatıldığını', 'Havalimanında yoğun kar yağdığını', 'Radarın arızalı olduğunu'], '\'Ceiling And Visibility OK\' anlamındaki CAVOK, görüşün 10 km ve üzerinde olduğunu, önemli bulut ve önemli hava olayı bulunmadığını belirtir.'),
  ('Yer eşzamanlı (sabit konumlu) meteoroloji uyduları ekvatorun yaklaşık 36 000 km üzerinde bulunur. Bu yörüngenin meteoroloji açısından en büyük yararı nedir?', 'Aynı bölgeyi sürekli izleyip birkaç dakikada bir görüntü almak', ['Kutup bölgelerini çok ayrıntılı görmek', 'Yere çok yakın dolandığı için olabilecek en yüksek çözünürlüğü sağlamak', 'Dünya\'nın tamamını tek seferde ve aynı açıyla görmek'], 'Bu uydular Dünya ile aynı hızda döndüğünden hep aynı yere bakar; fırtınaların gelişimini sürekli izlemek için idealdir, ancak kutuplar çok eğik açıdan görülür.'),
  ('Kutupsal yörüngeli meteoroloji uydularının yer eşzamanlı uydulara göre üstünlüğü hangisidir?', 'Alçakta dolanıp daha ayrıntılı görüntü almaları ve tüm Dünya\'yı taramaları', ['Aynı noktayı hiç ara vermeden izleyebilmeleri', 'Hiç yakıt ve enerji gerektirmemeleri', 'Yalnızca ekvatoru gözleyebilmeleri'], 'Yaklaşık 800 km yükseklikte kutuptan kutba dolanan bu uydular, Dünya döndükçe her yeri günde birkaç kez görür; ancak bir bölgeyi sürekli izleyemez.'),
  ('Kızılötesi uydu görüntülerinde bir fırtına bulutunun tepesinin çok parlak beyaz, alçak stratus bulutlarının ise neredeyse görünmez olmasının nedeni nedir?', 'Görüntü sıcaklığa göre boyanır; yüksek tepe çok soğuk, alçak bulut yere yakın sıcaklıktadır', ['Fırtına bulutları kızılötesi ışığı kendileri üretir', 'Stratus bulutları gece hiç bulunmaz', 'Kızılötesi kanal yalnızca su buharını ölçer'], 'Geleneksel gösterimde soğuk yüzeyler beyaz, sıcak yüzeyler koyu çizilir; sis ve alçak bulut yere benzer sıcaklıkta olduğundan ayırt etmek güçtür.'),
  ('Meteoroloji uydularının \'su buharı kanalı\' görüntüleri neyi gösterir?', 'Bulut olmasa bile orta ve üst troposferdeki nem dağılımını', ['Okyanus yüzeyindeki dalga yüksekliğini', 'Yeraltı sularının derinliğini', 'Yağmur damlalarının yere çarpma hızını ve toprağa sızan su miktarını'], 'Bu kanal su buharının güçlü soğurduğu dalga boyunu kullanır; jet akımları ve üst seviyedeki kuru, nemli bölgeler görünür hâle gelir.'),
  ('Doppler hava radarlarının sıradan radarlardan farkı nedir?', 'Yağış taneciklerinin radara yaklaşma ya da uzaklaşma hızını da ölçer', ['Yalnızca karı algılayabilir', 'Bulutların sıcaklığını ölçer', 'Radyo dalgası yerine yüksek frekanslı ses dalgaları kullanır'], 'Doppler kaymasından taneciklerin radyal hızı bulunur; birbirine çok yakın, zıt yönlü hızlar bir fırtınadaki dönmeyi (mezosiklonu) ortaya çıkarabilir.'),
  ('Çift kutuplamalı (dual-pol) hava radarlarının yatay ve dikey radyo atımları birlikte göndermesi hangi bilgiyi sağlar?', 'Taneciklerin biçim ve türünü ayırt etme olanağı', ['Yağışın kimyasal bileşimini ve asitlik derecesini', 'Bulutların yaşını', 'Yerdeki toprak nemini'], 'Yağmur damlaları yassı, dolu taneleri daha yuvarlak ve düzensizdir; iki kutuplamadaki yansımalar karşılaştırılarak yağmur, kar, dolu, hatta hortumun kaldırdığı enkaz ayırt edilebilir.'),
  ('Meteorologların hava sistemlerinin yönünü tahmin ederken sıklıkla incelediği 500 hPa haritası yaklaşık hangi yüksekliği temsil eder?', 'Yaklaşık 5,5 km', ['Deniz seviyesini', 'Yaklaşık 1,5 km', 'Yaklaşık 30 km'], '500 hPa yüzeyi troposferin ortasındadır; buradaki akış yüzeydeki alçak ve yüksek basınçları \'yönlendiren\' akım olarak kullanılır.'),
  ('Bir istasyon modelinde rüzgâr çizgisine bir üçgen bayrak ve iki uzun çentik eklenmiştir. Üçgen 50 knot, uzun çentik 10 knot, kısa çentik 5 knot anlamına geldiğine göre rüzgâr hızı kaç knottur?', '70', ['52', '60', '65'], '50 + 10 + 10 = 70 knot.'),
  ('Hava haritalarındaki istasyon modellerinde basınç son üç basamakla yazılır; ilk basamak 5\'ten küçükse başa 10, 5 veya büyükse 9 eklenip son basamaktan önce virgül konur. Bir istasyonun yanında \'089\' yazıyorsa basınç kaç hPa\'dır?', '1008,9', ['989,0', '908,9', '1089,0'], '0 rakamı 5\'ten küçük olduğundan başa 10 eklenir: 1008,9 hPa.'),
  ('Edward Lorenz 1961\'de bir hava modelini yeniden çalıştırırken bir sayıyı altı yerine üç ondalık basamağa yuvarlayarak girdiğinde birkaç hafta sonra tamamen farklı bir hava elde etti. Bu gözlem neyi gösterdi?', 'Başlangıç koşullarındaki çok küçük farkların zamanla büyüyebileceğini', ['Bilgisayarların hesap yaparken sık sık bozulduğunu', 'Hava tahmininin hiçbir koşulda ve hiçbir süre için işe yaramayacağını', 'Ondalık sayıların meteorolojide kullanılmaması gerektiğini'], 'Bu \'başlangıç koşullarına hassas bağımlılık\', kaos kuramının temelidir ve ayrıntılı hava tahminlerinin belli bir süreden öteye uzatılamamasının nedenidir.'),
  ('Lorenz\'in 1972\'deki bir konuşmasının başlığından yola çıkarak, küçük bir etkinin zamanla büyük sonuçlar doğurabileceğini anlatan ünlü benzetme hangisidir?', 'Kelebek etkisi', ['Domino ilkesi', 'Kartopu kuralı', 'Kuyruklu yıldız etkisi'], 'Konuşmanın başlığı Brezilya\'daki bir kelebeğin kanat çırpmasının Teksas\'ta bir hortuma yol açıp açamayacağını soruyordu.'),
  ('Günlük hava koşullarının ayrıntılı tahmini için kuramsal olarak öngörülebilirlik sınırı genellikle ne kadar kabul edilir?', 'Yaklaşık iki hafta', ['Yaklaşık iki saat', 'Yaklaşık iki ay', 'Sınırsız; yalnızca bilgisayar gücüne bağlı'], 'Gözlemler ve modeller ne kadar iyileşirse iyileşsin küçük hatalar büyüdüğünden, belirli bir günün havasını yaklaşık iki haftadan uzun süre önce ayrıntılı tahmin etmek mümkün görünmemektedir.'),
  ('Topluluk (ensemble) tahmininde aynı model, başlangıç koşulları birbirinden çok az farklı onlarca kez çalıştırılır. Bu çalıştırmaların sonuçları birbirinden çok farklı çıkarsa bu ne anlama gelir?', 'Tahminin belirsizliğinin yüksek olduğu', ['Modelin kesinlikle hatalı yazıldığı', 'Havanın o günlerde hiç değişmeyeceği ve tahminin kesin olduğu', 'Gözlemlerin tamamen yanlış olduğu'], 'Üyelerin yayılımı tahmine ne kadar güvenilebileceğini gösterir; üyeler birbirine yakınsa güven yüksek, çok dağınıksa düşüktür.'),
  ('Radar ve uydu görüntülerindeki yağış alanlarının hareketini birkaç saat ileri taşıyarak yapılan çok kısa süreli tahminlere ne ad verilir?', 'Anlık tahmin', ['Klimatolojik tahmin', 'Mevsimlik tahmin', 'Paleoklimatik (geçmiş iklim) tahmini'], 'Anlık tahmin genellikle 0–6 saatlik süreyi kapsar; ani sel ve şiddetli fırtına uyarılarında çok önemlidir.'),
  ('Dünya Meteoroloji Örgütü (WMO) hakkında aşağıdakilerden hangisi doğrudur?', 'Merkezi Cenevre\'de olan bir Birleşmiş Milletler uzman kuruluşudur', ['Merkezi Paris\'te bulunan bir Avrupa Birliği ajansıdır', 'Yalnızca meteoroloji uydusu fırlatmakla görevli, kâr amaçlı özel bir şirkettir', 'Merkezi New York\'ta olan bir uzay araştırma kurumudur'], 'WMO, 1873\'te kurulan Uluslararası Meteoroloji Örgütü\'nün devamıdır; 1950\'de kuruldu ve 1951\'de BM uzman kuruluşu oldu.'),
  ('Bulutsuz ve açık havada, çoğunlukla jet akımlarının kenarlarında yolcu uçaklarını aniden sarsan ve radarda görülemeyen olaya ne ad verilir?', 'Açık hava türbülansı', ['Mikropatlama', 'Dağ meltemi', 'Buzlanma'], 'Açık hava türbülansı, farklı hızlarda akan hava katmanları arasındaki kesmeden doğar; görünür bir işaret vermediği için yolcuların kemerlerini bağlı tutması önerilir.'),
  ('Sıcak bir yaz öğleden sonrasında yüksek rakımlı bir havalimanından kalkan uçağın, serin bir sabaha göre çok daha uzun pist mesafesine ihtiyaç duymasının nedeni nedir?', 'Sıcak ve yüksek yerde hava daha seyrek olduğundan kanat ve motorun verimi düşer', ['Sıcak havada pist asfaltı yumuşayıp kayganlaşır ve tekerlekler yerinde patinaj yapar', 'Öğleden sonra rüzgâr her zaman arkadan eser', 'Sıcak hava uçağın ağırlığını artırır'], 'Havacılıkta bu durum \'yoğunluk irtifası\' ile ifade edilir: sıcaklık, yükseklik ve nem arttıkça hava yoğunluğu azalır, uçak daha yüksek bir yerdeymiş gibi davranır.'),
  ('Pilotlar arasında \'yüksekten alçağa, dikkat aşağıya\' diye bilinen bir uyarı vardır. Basınç altimetresi ayarlanmadan yüksek basınç bölgesinden alçak basınç bölgesine uçan bir uçak için bu uyarının anlamı nedir?', 'Uçak, altimetrenin gösterdiğinden daha alçakta uçmaktadır', ['Uçak, altimetrenin gösterdiğinden daha yüksekte uçmaktadır', 'Altimetre basınçtan etkilenmediği için fark oluşmaz', 'Uçak alçak basınçta otomatik olarak yükselir'], 'Dış basınç düşünce altimetre uçağın tırmandığını sanır; pilot göstergeyi sabit tutmak için alçalır ve gerçekte yere beklenenden yakın uçar.'),
  ('Lentikular bulutların altında, dağların rüzgâr altı tarafında küçük uçakları şiddetle sarsan, dönen hava bölgesine ne ad verilir?', 'Rotor', ['Göz', 'Örs', 'Termik'], 'Güçlü dağ dalgalarının altında hava yatay eksenli girdaplar hâlinde döner; bu rotorlar bazen yırtık kümülüs parçalarıyla belirginleşir ve çok tehlikeli türbülans yaratır.'),
  ('\'Ay ağıl yaptı, yağmur gelecek\' gibi sözlerin dayandığı Ay çevresindeki halkanın, bir iki gün içinde yağış gelebileceğini düşündürmesinin nedeni nedir?', 'Haleyi oluşturan sirrostratus çoğu kez yaklaşan bir sıcak cephenin habercisidir', ['Hale Ay\'ın Dünya\'ya yaklaştığını gösterir', 'Hale yağmur damlalarının uzayda donmasıyla oluşur', 'Ay\'ın çekimi bulutları halka biçiminde toplar'], 'Sıcak cephe yaklaşırken gökyüzü önce sirrus, sonra sirrostratus ile kaplanır; ardından bulutlar kalınlaşıp yağış başlar.'),
  ('Sakin ve açık kış gecelerinde uzaktaki tren ya da otoyol seslerinin gündüze göre çok daha net duyulmasının meteorolojik nedeni nedir?', 'Yere yakın soğuk hava katmanı sesi kırarak yeniden yere doğru büker', ['Gece havası sesi hiç soğurmaz', 'Gece sesin hızı ışık hızına yaklaşır', 'Gece Ay\'ın çekimi ses dalgalarını yere doğru çeker'], 'Gece yer soğuyunca sıcaklığın yükseklikle arttığı bir katman oluşur; ses üst kısımda daha hızlı gittiğinden dalgalar aşağı doğru kırılıp uzak mesafelere taşınır.'),
  ('Atmosferin yer yüzeyinden doğrudan etkilenen, gündüz türbülansla iyi karışan ve kalınlığı genellikle birkaç yüz metre ile 1–2 km arasında değişen en alt kısmına ne ad verilir?', 'Gezegen sınır tabakası', ['Stratosfer', 'İyonosfer', 'Tropopoz'], 'Sınır tabakada sürtünme ve yüzey ısınması önemlidir; gündüz kalınlaşır, gece ise ışınımla soğuyan yüzey üzerinde incelir.'),
  ('Kararlı bir atmosferde zorla yükseltilen nemli hava ile kararsız bir atmosferde yükselen nemli hava genellikle hangi bulut türlerini oluşturur?', 'Kararlı havada katmanlı, kararsız havada kümülüs türü bulutlar', ['Her ikisinde de yalnızca sirrus bulutları', 'Kararlı havada kümülonimbus, kararsız havada stratus', 'Kararlı havada hiç bulut, kararsız havada yalnızca sis'], 'Kararlı havada hava kaldırılınca yatay olarak yayılır ve stratus türü katmanlar oluşur; kararsız havada parseller kendiliğinden yükselerek dikey gelişen bulutlar oluşturur.'),
  ('Havanın yükselmesini sağlayan mekanizmalardan hangisi, yerdeki rüzgârların bir bölgede birbirine doğru akarak havayı yukarı itmesine dayanır?', 'Yakınsama (konverjans)', ['Orografik kaldırma', 'Cephesel kaldırma (hava kütlesi sınırı)', 'Adveksiyon'], 'Yüzeyde yakınsayan hava yukarı kaçmak zorundadır; ekvatoral kuşakta ve deniz meltemi cephelerinde bu yolla bulut ve yağış oluşur.'),
  ('Florida yarımadasında yaz öğleden sonraları neredeyse her gün gök gürültülü sağanaklar görülmesinin önemli bir nedeni nedir?', 'İki kıyıdan gelen deniz meltemlerinin yarımadanın ortasında karşılaşması', ['Yarımadanın üzerinden her öğleden sonra düzenli olarak bir soğuk cephe geçmesi', 'Kıyılardaki dağların nemli havayı yükseltmesi', 'Bölgede her gün kutup havası çökmesi'], 'Atlantik ve Meksika Körfezi kıyılarından içeri ilerleyen meltem cepheleri kara üzerinde buluşur; yakınsayan nemli hava yükselerek fırtına bulutları oluşturur.'),
  ('Isıtma enerjisi ihtiyacını tahmin etmek için kullanılan \'derece-gün\' yönteminde bir gün için değer, taban sıcaklık ile günlük ortalama sıcaklık arasındaki fark olarak hesaplanır. Taban sıcaklık 18 °C, ortalama sıcaklıklar art arda üç gün 6 °C, 10 °C ve 13 °C olduğuna göre toplam ısıtma derece-gün değeri kaçtır?', '25', ['29', '22', '32'], '(18−6) + (18−10) + (18−13) = 12 + 8 + 5 = 25 derece-gün.'),
  ('Güney Asya\'da yaz musonunun güçlü olmasında Hindistan alt kıtasının yanı sıra hangi yüksek bölgenin yazın aşırı ısınması önemli rol oynar?', 'Tibet Platosu', ['Alp Dağları', 'Etiyopya Yaylası', 'Anadolu Platosu'], 'Yazın ısınan yüksek Tibet Platosu üst troposferde ısı kaynağı gibi davranır; kara ile Hint Okyanusu arasındaki basınç farkını güçlendirerek nemli güneybatı akımını besler.'),
  ('Hindistan\'da kış musonu döneminin genellikle kuru geçmesinin nedeni nedir?', 'Rüzgârların soğuk ve kuru kara içlerinden okyanusa doğru esmesi', ['Kışın Güneş\'in Hindistan\'ı hiç ısıtmaması', 'Kışın Hint Okyanusu yüzeyinin tamamen donması ve buharlaşmanın tümüyle durması', 'Kış rüzgârlarının yalnızca yüksek atmosferde esmesi'], 'Kışın kara okyanustan soğuk olduğundan basınç farkı ters döner; Asya içlerinden gelen kuzeydoğu rüzgârları nem taşımaz.'),
  ('Hindistan\'ın kuzeydoğusundaki Meghalaya eyaletinde Khasi Tepeleri\'nin güney yamaçlarındaki bazı köylerin dünyanın en yağışlı yerleri arasında sayılmasının nedeni nedir?', 'Nemli muson havasının dik yamaçlara çarpıp zorla yükselmesi', ['Bölgenin ekvatorun tam üzerinde bulunması', 'Bölgeye yağmur mevsiminde neredeyse her gün bir tropikal kasırganın ulaşması', 'Bölgedeki göllerden sürekli buharlaşma olması'], 'Bengal Körfezi\'nden gelen doymuş muson akımı tepelere çarpınca orografik olarak yükselir; Mawsynram ve Cherrapunji yıllık metrelerce yağış alır.'),
  ('Büyük orman yangınlarında, alevlerin oluşturduğu güçlü yükselici akımın dönmeye başlamasıyla oluşan, alevli ve dönen hava sütunlarına ne ad verilir?', 'Ateş girdabı', ['Su hortumu', 'Fön', 'Toz fırtınası'], 'Ateş girdapları yanan parçaları havaya kaldırıp uzaklara taşıyabilir ve yangını öngörülemez biçimde yayabilir.'),
  ('Okyanuslardan karalara uzanan, birkaç yüz km genişliğinde ancak binlerce km uzunluğunda, çok yoğun su buharı taşıyan dar kuşaklara ne ad verilir?', 'Atmosferik nehirler', ['Jet akımları', 'Okyanus akıntıları', 'Alize kuşakları'], 'Atmosferik nehirler dağlara çarptığında olağanüstü yağış ve sel üretebilir; ABD\'nin batı kıyısına Hawaii yönünden gelenlerine \'Pineapple Express\' denir.'),
  ('Meteorolojide \'sağanak fırtına\' (squall) ile \'hamle\' arasındaki fark en doğru nasıl açıklanır?', 'Sağanak fırtına dakikalarca süren ani güçlenme, hamle birkaç saniyelik sıçramadır', ['Hamle dakikalarca, sağanak fırtına birkaç saniye sürer', 'İkisi de yalnızca deniz üzerinde görülür', 'Hamle yalnızca kışın, sağanak fırtına yalnızca yazın görülür'], 'Sağanak fırtına rüzgârın aniden güçlenip en az yaklaşık bir dakika güçlü kalmasıdır; hamle ise rüzgârdaki birkaç saniyelik kısa sıçramalardır.'),
  ('Sahra\'dan kalkan toz bulutlarının yazın Atlas Okyanusu\'nu aşarak Karayipler\'e ve Güney Amerika\'ya ulaşabilmesini sağlayan başlıca akım hangisidir?', 'Doğudan esen alize rüzgârları', ['Batı rüzgârları kuşağı', 'Kutup doğu rüzgârları', 'Akdeniz üzerinde yazın esen etezyen rüzgârları'], 'Toz, tropikal kuşaktaki doğu rüzgârlarıyla batıya taşınır; uydu görüntülerinde okyanus üzerinde binlerce kilometrelik bulanık şeritler olarak görülür.'),
  ('Sahra tozunun okyanus üzerine yayıldığı dönemlerde Atlantik\'te tropikal kasırga oluşumunun zayıfladığı gözlenmiştir. Bunun olası nedenlerinden biri hangisidir?', 'Tozla gelen sıcak ve kuru havanın bulut gelişimini bastırması', ['Tozun deniz suyunu kaynatarak buharı yok etmesi', 'Toz taneciklerinin elektrik yükü taşıyarak gelişmekte olan kasırgaları itmesi', 'Tozun Coriolis etkisini ortadan kaldırması'], 'Sahra hava katmanı kuru ve sıcaktır; orta seviyede kararlılığı artırıp nemi azalttığı için gelişmekte olan sistemlerin güçlenmesini zorlaştırır.'),
  ('Deniz meltemi kara içine doğru ilerlerken önünde sıcaklığın birden düştüğü, nemin arttığı ve bazen kümülüs dizilerinin oluştuğu sınıra ne ad verilir?', 'Deniz meltemi cephesi', ['Kutup cephesi', 'Kapalı cephe', 'Kuru hat'], 'Serin deniz havası ılık kara havasını küçük ölçekli bir soğuk cephe gibi kaldırır; bu cephe yazın kıyıya yakın bölgelerde öğleden sonra sağanaklarını tetikleyebilir.'),
  ('Deniz meltemi açık ve güneşli günlerde güçlü olurken bulutlu ve rüzgârlı günlerde neredeyse hiç gelişmez. Bunun nedeni nedir?', 'Bulutlu havada kara yeterince ısınamadığından kara-deniz sıcaklık farkı küçük kalır', ['Bulutlu günlerde deniz karadan daha hızlı ısınır ve meltemin yönünü tersine çevirir', 'Bulutlar meltemi yukarıdan bastırıp tamamen durdurur', 'Rüzgârlı günlerde deniz çekilir ve kıyı uzaklaşır'], 'Meltem kara ile deniz arasındaki ısınma farkından doğar; bu fark küçükse ya da kuvvetli genel rüzgâr meltemi bastırıyorsa yerel dolaşım belirginleşmez.'),
  ('Dağ geçitlerinden ve dar boğazlardan geçen rüzgârın açık arazideki rüzgârdan çok daha hızlı esmesi hangi etkiyle açıklanır?', 'Daralan kesitte havanın hızlanması', ['Geçitlerde havanın yoğunluğunun sıfırlanması', 'Dağların rüzgârı ısıtıp hafifletmesi ve böylece daha hızlı akmasını sağlaması', 'Geçitlerde yerçekiminin azalması'], 'Aynı hava miktarı daha dar bir kesitten geçmek zorunda kaldığında hızlanır; bu yüzden boğaz ve vadilerde rüzgâr çevresine göre güçlü eser.'),
  ('Yüksek binaların arasındaki dar sokaklarda ve gökdelenlerin dibinde yayaların ani ve güçlü rüzgârlarla karşılaşmasının nedeni nedir?', 'Binaların rüzgârı aşağı yönlendirmesi ve dar aralıklarda hızlandırması', ['Binaların kendi ısısıyla rüzgâr üretmesi', 'Asfaltın rüzgârı yerden yukarı itmesi', 'Gökdelenlerin çevrelerindeki hava basıncını yükseltip havayı dışarı püskürtmesi'], 'Yüksek bina cephesine çarpan rüzgârın bir kısmı aşağı doğru döner, binalar arasındaki dar geçitler ise havayı kanal etkisiyle hızlandırır.'),
  ('Kar yağarken gök gürültüsü duyulması ve yıldırım görülmesi (gök gürültülü kar yağışı) için hangi değerlendirme doğrudur?', 'Nadirdir; kışın güçlü yükselici akımlar seyrek oluşur', ['Her kar yağışında görülür; kar taneleri sürtünmeyle sürekli yük üretir', 'Olanaksızdır; kar bulutlarında hiçbir koşulda elektrik yükü ayrışmaz', 'Yalnızca kutup gecesinde ve yalnızca açık deniz üzerinde görülebilir'], 'Yük ayrışması için güçlü yükselici akımlarla taşınan buz ve kar topağı tanecikleri gerekir; kış havasında bu kadar kararsızlık seyrek oluştuğundan gök gürültülü kar yağışı nadir ama mümkündür.'),
  ('Doymamış bir hava parseli yerde 28 °C sıcaklıktadır ve kuru adyabatik olarak (yaklaşık 10 °C/km) 1,5 km yükseltiliyor. Yoğuşma olmadığı varsayılırsa parselin yeni sıcaklığı yaklaşık kaç °C olur?', '13 °C', ['18,5 °C', '3 °C', '23 °C'], '1,5 km × 10 °C/km = 15 °C soğuma; 28 − 15 = 13 °C.'),
  ('Bir odada havadaki gerçek buhar basıncı 12 hPa, o sıcaklıktaki doymuş buhar basıncı ise 24 hPa\'dır. Odadaki bağıl nem yaklaşık yüzde kaçtır?', '%50', ['%12', '%24', '%200'], 'Bağıl nem = gerçek buhar basıncı / doymuş buhar basıncı × 100 = 12 / 24 × 100 = %50.'),
  ('Hacmi 60 m³ olan bir sınıfın havasında metreküp başına 9 gram su buharı bulunduğu ölçülmüştür. Sınıf havasındaki toplam su buharı kaç gramdır?', '540 g', ['69 g', '150 g', '6,7 g'], 'Toplam buhar = mutlak nem × hacim = 9 g/m³ × 60 m³ = 540 g.'),
  ('Bir hava radarının gönderdiği atımın bir yağış alanından yansıyıp geri dönmesi 0,4 milisaniye sürmüştür. Radyo dalgalarının hızı saniyede yaklaşık 300 000 km olduğuna göre yağış alanı radardan yaklaşık kaç km uzaktadır?', '60 km', ['120 km', '30 km', '240 km'], 'Dalga 0,4 ms\'de gidip döner: 300 000 km/s × 0,0004 s = 120 km toplam yol; uzaklık bunun yarısı, yani 60 km\'dir.'),
  ('Bir istasyonda saat 06.00\'da 1018 hPa olan basınç, öğlen 12.00\'de 1006 hPa ölçülmüştür. Ortalama basınç değişimi saatte kaç hPa\'dır ve bu neyi düşündürür?', '2 hPa/sa düşüş; yaklaşan bir alçak basınç sistemi', ['2 hPa/sa artış; bölgeye yerleşen güçlü bir yüksek basınç alanı', '12 hPa/sa düşüş; kesin bir hortum geçişi', '6 hPa/sa artış; açık ve durgun hava'], '(1018 − 1006) / 6 = 2 hPa/sa düşüş. Bu kadar hızlı düşüş, bölgeye yaklaşan bir alçak basınç ve kötüleşen havaya işaret eder.'),
  ('Okyanus üzerindeki stratokümülüs bulut örtülerinin uydu görüntülerinde gemilerin geçtiği rotalar boyunca daha parlak çizgiler hâlinde görülmesinin nedeni nedir?', 'Gemi bacasından çıkan parçacıkların daha çok sayıda ve daha küçük damlacık oluşturması', ['Gemilerin pervanelerinin ve gövdelerinin bulutu fiziksel olarak yararak arkasında iz bırakması', 'Gemilerin ışıklarının bulutu aydınlatması', 'Gemi gövdelerinin Güneş ışığını yukarı yansıtması'], 'Ek yoğuşma çekirdekleri aynı su miktarını daha fazla sayıda küçük damlacığa böler; bu tür bulutlar Güneş ışığını daha çok yansıtır ve \'gemi izleri\' parlak görünür.'),
  ('Yıldırımların atmosfer kimyasına önemli bir katkısı aşağıdakilerden hangisidir?', 'Havadaki azot ve oksijeni birleştirerek azot oksitler oluşturması', ['Havadaki argonu oksijene dönüştürmesi', 'Atmosferdeki su buharını tümüyle parçalayıp hidrojeni uzaya kaçırması', 'Atmosferdeki karbondioksiti yok etmesi'], 'Yıldırım kanalındaki çok yüksek sıcaklık, normalde tepkimeye girmeyen azot moleküllerini parçalar; oluşan azot oksitler yağışla toprağa ulaşarak doğal azot bağlanmasına katkı yapar.'),
  ('Lazer ışını gönderip havadaki parçacıklardan geri saçılan ışığı ölçen \'lidar\' cihazları meteorolojide en çok ne için kullanılır?', 'Toz, duman ve bulut katmanlarının yüksekliğini ve yoğunluğunu belirlemek için', ['Toprağın farklı derinliklerdeki sıcaklığını ve nemini uzaktan ölçmek için', 'Yıldırımların sesini kaydetmek için', 'Deniz suyunun tuzluluğunu ölçmek için'], 'Lidar ışınının geri dönüş süresi ve şiddeti, aerosol katmanlarının ve sınır tabakanın yapısının ayrıntılı biçimde çıkarılmasını sağlar.'),
  ('Kuzey Yarımküre\'de bir kişi doğuya bakarken soğuk bir cephenin geçtiğini ve rüzgârın güneybatıdan kuzeybatıya döndüğünü fark ediyor. Rüzgâr yönü nasıl değişmiştir?', 'Saat yönünde dönmüştür', ['Saat yönünün tersine dönmüştür', 'Hiç değişmemiştir', 'Tam tersine dönmüştür'], 'Güneybatıdan (225°) kuzeybatıya (315°) geçiş, derece değerinin arttığı, yani saat yönünde bir dönüştür; soğuk cephe geçişinde Kuzey Yarımküre\'de tipiktir.'),
  ('Yaz aylarında Kuzey Afrika\'dan Türkiye\'nin güney kesimlerine ulaşan bir hava kütlesinin birkaç gün içinde hangi hava koşullarını getirmesi beklenir?', 'Çok sıcak, kuru ve tozlu hava', ['Soğuk ve karlı hava', 'Serin, nemli ve sisli hava', 'Uzun süreli çisentili ve kapalı hava'], 'Sahra kaynaklı karasal tropikal hava çok sıcak ve kurudur; sıcak hava dalgası ve tozlu, puslu gökyüzü getirebilir.'),
  ('Bir meteoroloji istasyonunda anemometre bir binanın hemen yanına, yerden 3 m yüksekliğe yerleştirilmiştir. Bu istasyonun rüzgâr verileri için hangi değerlendirme en doğrudur?', 'Bina rüzgârı engelleyip saptırdığından değerler gerçek rüzgârı temsil etmez', ['Değerler standart ölçümden kesinlikle daha yüksek ve daha doğru olur, çünkü bina rüzgârı toplar', 'Rüzgâr ölçümü yükseklik ve engellerden etkilenmez', 'Değerler yalnızca gece yanlış, gündüz doğru olur'], 'Standart ölçüm engelsiz açık alanda 10 m yükseklikte yapılır; bina ve yere yakınlık hem hızı düşürür hem yönü bozar.'),
  ('Uydular her gün tüm Dünya\'yı taradığı hâlde meteoroloji servislerinin hâlâ balonla radyosonde göndermeyi sürdürmesinin en güçlü gerekçesi hangisidir?', 'Atmosferin içinden doğrudan ve dikeyde çok ayrıntılı ölçüm yapması', ['Uydulardan çok daha ucuz olduğu için uyduların yerini tamamen alabilmesi', 'Uyduların gece hiçbir ölçüm yapamaması ve radyosondenin bu açığı kapatması', 'Balonların yağmuru durdurarak ölçüm alanını kurutması'], 'Radyosondeler sıcaklık, nem ve rüzgârı yerinde ölçer; dikey çözünürlükleri yüksektir ve uydu ölçümlerinin doğrulanıp düzeltilmesinde referans olarak kullanılır.'),
  ('13. yüzyılda Japonya\'yı istila etmeye çalışan Moğol donanmalarını dağıttığı anlatılan fırtınalar için Japonların kullandığı \'kamikaze\' sözcüğünün anlamı nedir?', 'İlahi rüzgâr', ['Kızıl güneş', 'Ölüm rüzgârı', 'Kuzey fırtınası'], '1274 ve 1281\'deki istila girişimlerinde donanmalar büyük olasılıkla tayfunlarla dağıldı; Japonlar bu fırtınaları tanrıların gönderdiği \'ilahi rüzgâr\' olarak yorumladı.'),
  ('1588\'de İspanyol Armadası\'nın İngiltere seferinden dönerken İskoçya ve İrlanda kıyılarında çok sayıda gemi kaybetmesinde hangi etken belirleyici olmuştur?', 'Kuzey Atlantik\'in şiddetli fırtınaları', ['Akdeniz\'de oluşup Atlantik\'e geçen bir tropikal kasırganın gemileri batırması', 'Kuzey Denizi\'nin tamamen donması', 'Uzun süren rüzgârsızlık ve sıcak hava'], 'Armada, Manş\'tan geçemeyince Britanya Adaları\'nın kuzeyini dolaşmak zorunda kaldı; sonbahar fırtınaları birçok gemiyi kayalık kıyılara sürükledi.'),
  ('Hava radarında yay biçiminde öne doğru bükülen bir fırtına hattı (yay yankısı) görülmesi meteorologlar için neyin işaretidir?', 'Yayın ortasında güçlü düz çizgisel rüzgârların esmesi', ['Fırtınanın hızla dağılmakta olduğu', 'Bölgede kar yağışının başlayacağı', 'Fırtınanın dönüşünü tamamen yitirdiği ve zararsız olduğu'], 'Fırtına hattının arkasından gelen kuvvetli bir hava akımı hattın ortasını öne iter; yayın tepe noktası çevresinde yıkıcı rüzgârlar görülür.'),
  ('Bazı büyük hortumların içinde ana girdabın çevresinde dönen birkaç küçük girdap bulunur. Bu yapı, hortumun geçtiği yolda bir evin yıkılıp hemen yanındakinin sağlam kalmasını nasıl açıklar?', 'Küçük girdapların bulunduğu dar şeritlerde rüzgâr çok daha şiddetlidir', ['Hortum her evin önünde durup karar verir', 'Sağlam kalan evlerin kapı ve pencereleri açık bırakıldığı için basınç eşitlenmiştir', 'Hortum yalnızca belirli renkteki evlere zarar verir'], 'Çok girdaplı hortumlarda ana dönüşe eklenen alt girdaplar dar alanlarda rüzgârı aşırı artırır; hasar bu yüzden şeritler hâlinde ve düzensiz görülür.'),
  ('Hava olaylarının ölçeklere ayrılmasında birkaç bin kilometre boyutunda ve günlerce süren cepheler ile siklonlar hangi ölçeğe girer?', 'Sinoptik ölçek', ['Mikro ölçek', 'Mezo ölçek', 'Laboratuvar ölçeği'], 'Mikro ölçek metrelerden birkaç kilometreye (toz girdabı), mezo ölçek birkaç kilometreden yüzlerce kilometreye (fırtına hattı), sinoptik ölçek ise binlerce kilometreye (siklon) karşılık gelir.'),
  ('Uydu görüntülerinde soğuk havanın ılık deniz üzerine aktığı günlerde rüzgâr yönüne paralel uzanan düzenli kümülüs dizileri görülür. Bu desenlere ne ad verilir?', 'Bulut sokakları', ['Gemi izleri', 'Bulut delikleri', 'Yay yankıları'], 'Sınır tabakadaki yatay eksenli dönen hava silindirleri, yükselen kollarda kümülüs sıraları, alçalan kollarda bulutsuz şeritler oluşturur.'),
  ('Londra türü dumanlı sis ile Los Angeles türü fotokimyasal duman (smog) karşılaştırıldığında, fotokimyasal dumanın oluşumunda hangi meteorolojik etken belirleyicidir?', 'Güçlü güneş ışığı', ['Yoğun kar yağışı', 'Kuvvetli fırtına rüzgârları', 'Kış gecelerinin uzunluğu'], 'Fotokimyasal dumanda araç egzozundaki azot oksitler ve hidrokarbonlar güneş ışığıyla tepkimeye girip ozon üretir; bu yüzden güneşli, sıcak ve durgun yaz günlerinde görülür.'),
  ('Bir kentte hava kirliliği kışın, rüzgârsız ve yüksek basınçlı günlerde en kötü düzeye çıkıyor, bir soğuk cephe geçince birden iyileşiyor. Cephe geçişinin etkisi en iyi nasıl açıklanır?', 'Cephenin getirdiği rüzgâr ve karışım kirli havayı dağıtır', ['Soğuk cephe kirleticileri kimyasal olarak birkaç dakika içinde tamamen yok eder', 'Cephe kent üzerindeki kirli havayı yere bastırır', 'Cephe sırasında fabrikalar kendiliğinden durur'], 'Durgun yüksek basınç dönemlerinde kirleticiler alçak bir katmanda birikir; cephe geçişiyle artan rüzgâr ve kararsızlık bu havayı karıştırıp temizler.'),
  ('Yollarda tuz kullanımının çok soğuk günlerde (örneğin −20 °C\'de) etkisini büyük ölçüde yitirmesinin nedeni nedir?', 'Tuzlu suyun donma noktası ancak belirli bir değere kadar düşürülebilir', ['Tuz soğukta buharlaşıp havaya karışır', 'Soğuk havada tuz kristalleri karı ısıtır', 'Düşük sıcaklıkta tuz suya hiç çözünmez ve buz gibi davranır'], 'Sofra tuzu suyun donma noktasını yaklaşık −21 °C\'ye kadar düşürebilir; pratikte −10 °C\'nin altında etkinliği hızla azalır, bu yüzden çok soğukta kum ya da başka kimyasallar tercih edilir.'),
  ('İlkbaharda Türkiye\'ye güneyden ılık ve nemli hava taşıyan bir sistem geçerken kar örtüsü bulunan dağlık alanlarda hangi risk birden artar?', 'Hızlı kar erimesine bağlı taşkın', ['Kuraklığın derinleşmesi', 'Göllerin donması', 'Hortum oluşumu ve yıkıcı düz rüzgârlar'], 'Ilık hava ve yağmur birlikte karı hızla eritir; akarsulara aynı anda büyük miktarda su ulaşınca taşkın riski yükselir.'),
  ('Bir hortumun yaşamının son evresinde ince, kıvrımlı bir ip gibi görünmesi genellikle neyi gösterir?', 'Hortumun zayıflayıp dağılmak üzere olduğunu', ['Hortumun en güçlü evresine girdiğini', 'Hortumun yağmur yağdırmaya başladığını', 'Hortumun ikinci bir hortumla birleşerek büyüdüğünü'], 'Hortumu besleyen yükselici akımla bağlantı zayıfladığında girdap incelir ve gerilip kıvrılır; ip evresi çoğu zaman sona yaklaşıldığını gösterse de bu evrede de hasar verebilir.'),
  ('Dünyadaki hortumların büyük bölümünün Kuzey Amerika\'nın orta kesimlerinde görülmesi en iyi hangi coğrafi-meteorolojik koşulla açıklanır?', 'Körfezin nemli, çölün kuru ve Kanada\'nın soğuk havasının engelsiz ovalarda buluşması', ['Bölgenin ekvatorun hemen üzerinde bulunması ve yıl boyu kasırga alması', 'Ovaların denizden yüksek dağlarla tamamen kapalı olması ve havanın durgunlaşması', 'Bölgede kış boyunca sürekli kar yağması ve kar örtüsünün havayı döndürmesi'], 'Doğu-batı uzanan dağ engeli olmadığından farklı hava kütleleri kolayca buluşur; bu karşılaşma güçlü kararsızlık ve rüzgâr kesmesi üreterek süper hücreler için ideal ortam yaratır.'),
  ('Dünya\'nın doğal sera etkisine en büyük katkıyı yapan gaz hangisidir?', 'Su buharı', ['Azot', 'Oksijen', 'Argon'], 'Su buharı kızılötesini güçlü biçimde soğurur ve miktarı da fazladır; ancak miktarı sıcaklığa bağlı olduğundan iklim değişiminde daha çok bir güçlendirici (geri besleme) olarak davranır.'),
  ('Ekvator bölgesi yıl boyunca yaydığından fazla enerji alırken kutuplar aldığından fazlasını yayar. Buna karşın ekvatorun giderek ısınmamasını ve kutupların giderek soğumamasını sağlayan nedir?', 'Atmosfer ve okyanusların ısıyı kutuplara doğru taşıması', ['Ekvatora gelen fazla enerjinin bulutlarla hemen ve tamamen uzaya yansıtılması', 'Kutupların Güneş\'ten ek enerji alması', 'Dünya\'nın dönüşünün sıcaklıkları eşitlemesi'], 'Rüzgârlar, fırtınalar ve okyanus akıntıları sürekli olarak düşük enlemlerden yüksek enlemlere ısı taşır; hava sistemlerinin varlığı büyük ölçüde bu dengeleme ihtiyacından kaynaklanır.'),
  ('Kar ve buz örtüsü eridikçe yeryüzünün daha çok güneş ışınımı soğurup daha da ısınması, bunun da daha çok erimeye yol açması hangi sürece örnektir?', 'Pozitif geri besleme', ['Negatif geri besleme', 'Adyabatik soğuma', 'Sıcaklık terselmesi'], 'Erime albedoyu düşürür, soğurulan enerji artar ve erime hızlanır; ilk değişimi güçlendiren bu tür döngülere pozitif geri besleme denir.'),
  ('Bazı meyve bahçelerinde don gecelerinde çalıştırılan büyük pervaneli \'rüzgâr makineleri\' hangi ilkeyle koruma sağlar?', 'Yukarıdaki görece ılık havayı yere yakın soğuk katmanla karıştırarak', ['Havayı elektrikle ısıtıp ağaçlara üfleyerek', 'Bulutları ağaçların üzerine çekerek', 'Toprağı kazıyıp derindeki sıcak havayı yüzeye çıkararak ağaçların çevresine yaymak suretiyle'], 'Açık sakin gecelerde yere yakın hava en soğuktur ve birkaç on metre yukarısında daha ılık bir katman bulunur; pervaneler bu terselmeyi bozarak yer sıcaklığını yükseltir.'),
  ('Bir mühendis, bir köprünün \'100 yılda bir görülen\' sele dayanacak biçimde tasarlandığını söylüyor. Bu ifade için en doğru değerlendirme hangisidir?', 'Bu büyüklükteki bir selin herhangi bir yılda görülme olasılığı yaklaşık %1\'dir', ['Böyle bir sel tam olarak her 100 yılda bir kez görülür', 'Böyle bir sel geçen yıl yaşandıysa önümüzdeki 99 yıl boyunca kesinlikle yaşanmayacaktır', 'Böyle bir sel 100 yıl içinde kesinlikle bir kez olacaktır'], 'Yinelenme süresi bir olasılık ifadesidir; \'100 yıllık\' olay art arda iki yıl da görülebilir ya da 100 yıl boyunca hiç görülmeyebilir.'),
  ('Güzel havalarda görülen, küçük, yassı ve dikey gelişimi zayıf \'kümülüs humilis\' bulutları ile kule gibi yükselen \'kümülüs kongestus\' bulutlarının farkı neyi gösterir?', 'Atmosferin kararsızlık derecesini', ['Bulutların içinde çözünmüş tuz ve toz miktarını', 'Güneş\'in Dünya\'ya uzaklığını', 'Yerdeki toprak türünü'], 'Humilis türü, yükselen havanın sığ bir katmanla sınırlı olduğunu; kongestus ise havanın daha kararsız olup derin bir katman boyunca yükseldiğini gösterir ve sağanak habercisi olabilir.'),
  ('Bulut adlarında kullanılan \'fraktus\' tür adı bulutun hangi görünümünü anlatır?', 'Yırtık, parçalı görünüm', ['Dalgalı görünüm', 'Mercek biçimi', 'Kale burcu biçiminde yükselen tepeler'], 'Fraktus, düzensiz ve kenarları yırtık bulut parçalarını tanımlar; yağış sırasında bulut tabanının altında süzülen parçalar sık görülür.'),
  ('Bulut adlarına eklenen \'undulatus\' çeşit adı neyi belirtir?', 'Dalgalı bir desen gösterdiğini', ['Yağış bıraktığını', 'Çok parlak olduğunu', 'Kule gibi yükseldiğini ve dolu yağdıracağını'], 'Undulatus, rüzgâr kesmesinin yarattığı dalgalanmalarla bulutun düzenli sıralar ya da dalgalar hâlinde görünmesini anlatır.'),
  ('Rüzgâr kategorisi düşük olan yavaş hareketli bir tropikal siklonun bazen güçlü ama hızlı geçen bir kasırgadan çok daha fazla sel hasarına yol açmasının nedeni nedir?', 'Yavaş ilerleyen sistem aynı bölgeye günlerce yağış bırakır', ['Düşük kategorili fırtınaların yağmuru daha tuzludur', 'Hızlı ilerleyen güçlü kasırgalar karaya çıktığında hiç yağış bırakmaz', 'Yavaş fırtınalar deniz suyunu ısıtıp kaynatır'], 'Saffir-Simpson ölçeği yalnızca rüzgârı dikkate alır; toplam yağış büyük ölçüde sistemin ne kadar süre aynı yerde kaldığına bağlıdır.'),
  ('Dünya genelinde ticari yolcu uçaklarının uçuş sırasında otomatik olarak gönderdiği sıcaklık ve rüzgâr ölçümleri meteorolojide neden değerlidir?', 'Okyanuslar gibi gözlemin seyrek olduğu yerlerde üst hava verisi sağlar', ['Uçakların yakıtını azaltarak havayı temizler', 'Yağmuru uçağın kanatlarında ölçerek hava radarlarının yerini tamamen alabilir', 'Uçaklar yalnızca kalkışta ölçüm yaptığı için yer verisi sağlar'], 'Uçak gözlemleri, özellikle kalkış-iniş sırasında dikey profiller ve seyir irtifasında rüzgâr ile sıcaklık verisi sağlayarak tahmin modellerinin başlangıç durumunu iyileştirir.'),
  ('Havacılıkta yayımlanan \'SIGMET\' mesajları hangi amaçla kullanılır?', 'Uçuş güvenliğini etkileyen tehlikeli hava olaylarını belirli bir bölge için duyurmak', ['Havalimanlarının günlük yolcu sayısını bildirmek', 'Bir havalimanının yalnızca sıcaklığını bildirmek', 'Uçakların bakım zamanını ve yakıt ikmali için uygun havalimanlarını hatırlatmak'], 'SIGMET; şiddetli türbülans, şiddetli buzlanma, gök gürültülü fırtına hatları, volkanik kül ve tropikal siklon gibi olaylar için yayımlanan uyarılardır.'),
  ('Arabistan ve Sahra çöllerinde esen, çok sıcak, kuru ve tozlu olduğu için \'zehirli rüzgâr\' diye de anılan ve Türkçede samyeli olarak bilinen rüzgâr hangisidir?', 'Simum', ['Bora', 'Pampero', 'Mistral'], 'Samyeli (simum) kısa süreli ama boğucu bir çöl rüzgârıdır; sıcaklığı çok yükseltir ve kum-toz taşır.'),
  ('And Dağları\'nın doğu yamaçlarından Arjantin\'e inen, kuru ve sıcak \'Zonda\' rüzgârı hangi rüzgâr türüne örnektir?', 'Fön rüzgârı', ['Deniz meltemi', 'Muson rüzgârı', 'Alize rüzgârı'], 'Pasifik\'ten gelen hava And Dağları\'nı aşarken nemini bırakır; doğu yamaçtan inerken ısınıp kuruyarak Zonda\'yı oluşturur.'),
  ('ABD\'nin doğu kıyısında, özellikle kışın kıyı boyunca kuzeye ilerleyen ve kuzeydoğudan esen kuvvetli rüzgârlarla yoğun kar ve kıyı taşkınlarına yol açan fırtınalara ne ad verilir?', 'Nor\'easter', ['Santa Ana', 'Chinook', 'Haboob'], 'Bu ılıman enlem siklonları Atlantik\'in ılık sularından nem alır; merkezin kuzeybatısında kalan kentlere kar ve kuzeydoğu rüzgârları getirir.'),
  ('Rusya ve Orta Asya bozkırlarında kışın karı savurarak tipiye dönüşen kuvvetli kuzeydoğu rüzgârının adı nedir?', 'Buran', ['Sirocco', 'Hamsin', 'Levante'], 'Buran, bozkırlarda görüşü sıfıra yaklaştırabilen soğuk ve şiddetli bir rüzgârdır; tundrada benzer rüzgâra purga denir.'),
  ('Rüzgârın bir yüzeye uyguladığı basınç yaklaşık olarak hızın karesiyle orantılıdır. Rüzgâr hızı 50 km/sa\'ten 100 km/sa\'e çıktığında bir duvara etkiyen rüzgâr yükü yaklaşık kaç katına çıkar?', '4 katına', ['2 katına', '8 katına', '16 katına'], 'Hız 2 katına çıktığında basınç 2² = 4 katına çıkar; bu yüzden fırtına rüzgârlarında hasar hızla artar.'),
  ('Ev barometrelerinin kadranında yazan \'Fırtına\', \'Yağmur\', \'Değişken\', \'Güzel\' gibi ifadelere ilişkin en doğru değerlendirme hangisidir?', 'Tek bir değer yerine basıncın son saatlerdeki değişim yönü daha güvenilir bilgi verir', ['Kadran yazıları her yerde ve her koşulda kesin sonuç verir', 'Barometre basınç değil, doğrudan yağış miktarını ölçer', 'Kadran yazıları yalnızca deniz seviyesinin çok üstündeki dağ istasyonlarında doğru sonuç verir'], 'Aynı basınç değeri farklı yüksekliklerde ve hava durumlarında farklı anlama gelir; hızla düşen basınç kötüleşen havanın, yükselen basınç ise düzelmenin daha iyi göstergesidir.'),
  ('Bir yağmur damlası yerdeki bir gözlemciye ulaşmadan önce bulut tabanının altındaki kuru havadan geçerken küçülüyor. Bu durum hangi bölgelerde daha belirgin görülür?', 'Bulut tabanı yüksek ve alt katmanı kuru olan bölgelerde', ['Bulut tabanı yere değen sisli bölgelerde', 'Havanın tamamen doymuş olduğu sıcak ve nemli yağmur ormanlarında', 'Kutuplarda kar yağarken'], 'Kurak bölgelerde yağış buluttan düştükten sonra kuru havada buharlaşır; buharlaşma bazen virgaya, yerde ise serinletici aşağı akımlara yol açar.'),
  ('Kar yağışı sırasında tanelerin bazen tek tek kristaller yerine büyük, yumuşak \'kar yaprakları\' hâlinde düşmesi en çok hangi koşulda görülür?', 'Sıcaklık 0 °C\'ye yakın ve hava nemliyken', ['Sıcaklık −30 °C\'nin altında ve hava kuruyken', 'Rüzgâr çok kuvvetliyken ve bulut yokken', 'Yalnızca kutup gecesinde ve stratosferde'], '0 °C\'ye yakın sıcaklıklarda kristallerin yüzeyi ıslak ve yapışkan olur; çarpışan kristaller birbirine tutunarak iri kar yaprakları oluşturur.'),
  ('Bir hava kütlesinin \'kaynak bölgesi\' olabilmesi için o bölgenin genellikle hangi özelliği taşıması gerekir?', 'Geniş, düzgün yüzeyli ve havanın uzun süre durgun kalabildiği bir alan olması', ['Çok dağlık ve engebeli olması', 'Dar bir boğaz olması', 'Sürekli kuvvetli rüzgâr alan ve havanın sık sık yenilendiği bir bölge olması'], 'Havanın sıcaklık ve nem özelliklerini kazanması için büyük okyanuslar, geniş ovalar ya da buz örtüleri üzerinde günlerce durgun kalması gerekir.'),
  ('Kuru ve sıcak bir bölgede yağışını yere ulaştıramayan, ancak çok sayıda yıldırım üreten \'kuru fırtınalar\' neden tehlikelidir?', 'Yağmur olmadan düşen yıldırımlar orman yangınları başlatabilir', ['Kuru fırtınalar yağış bırakmadığı hâlde her zaman büyük seller getirir', 'Kuru fırtınalarda hava hiç hareket etmez', 'Bu fırtınalar karı eritip çığa yol açar'], 'Yağış kuru alt katmanda buharlaşır ve yere ulaşmaz; yıldırımın tutuşturduğu kuru bitki örtüsünü söndürecek yağmur düşmediği için yangınlar hızla büyüyebilir.'),
  ('Tropikal siklonların uydu görüntülerinde bazen merkezin üzerinde, göz duvarındaki bulutların tepesinden dışarı doğru yayılan ince bulut örtüsü görülür. Bu örtü neyin sonucudur?', 'Yukarıda fırtınadan dışarı doğru akan havanın', ['Fırtınanın içine yukarıdan çekilen soğuk havanın', 'Uzaydan gelen toz bulutunun', 'Okyanus yüzeyinden yükselen tuz kristallerinin'], 'Tropikal siklonlarda yerde merkeze doğru akan hava yükselir ve üst troposferde dışarıya doğru yayılır; bu dışa akış sirrus örtüsü olarak görülür ve fırtınanın sağlığı için önemlidir.'),
  ('Bir kasırganın üzerinde güçlü batı rüzgârları esmeye başladığında (kuvvetli dikey rüzgâr kesmesi) kasırga genellikle nasıl etkilenir?', 'Yapısı bozulup zayıflar', ['Daha da güçlenir ve gözü küçülür', 'Hiçbir biçimde etkilenmez', 'Hemen tropik depresyondan kasırgaya dönüşür'], 'Dikey rüzgâr kesmesi fırtınanın üst kısmını alt kısmından ayırıp eğer; sıcak çekirdek dağılır ve sistem zayıflar.'),
  ('Büyük bir gölün kıyısındaki bağların, aynı bölgede gölden uzak bağlara göre ilkbahar ve sonbahar donlarından daha az etkilenmesinin nedeni nedir?', 'Göl suyunun ısıyı depolayıp gece çevresini ılıtması', ['Göl kıyısında Güneş\'in her gün daha uzun süre görünmesi ve toprağı ısıtması', 'Göl suyunun havadaki oksijeni artırması', 'Göl kıyısında rüzgârın hiç esmemesi'], 'Su yavaş soğur; gece göl yüzeyinden gelen ısı ve nem kıyı şeridindeki havanın donma noktasının altına inmesini geciktirir.'),
  ('Bir istasyonda bir hafta boyunca ölçülen en düşük sıcaklıklar −3, 1, −1, 2, 0, −4 ve 3 °C\'dir. \'Don günü\' en düşük sıcaklığın 0 °C\'nin altında olduğu gün olarak tanımlandığına göre bu haftada kaç don günü vardır?', '3', ['2', '4', '5'], '0 °C\'nin altındaki değerler −3, −1 ve −4\'tür; 0 °C ölçülen gün don günü sayılmaz. Toplam 3 don günü.'),
  ('Orman yangınlarının çoğunlukla öğleden sonra en hızlı yayılmasının meteorolojik nedeni nedir?', 'O saatlerde sıcaklık en yüksek, bağıl nem en düşük ve rüzgâr daha kuvvetlidir', ['Öğleden sonra hava basıncı sıfıra iner', 'Öğleden sonra Güneş ışınları kuru bitkileri büyüteç gibi odaklanarak doğrudan tutuşturur', 'Öğleden sonra ormanlarda oksijen miktarı iki katına çıkar'], 'Günlük döngüde sıcaklık öğleden sonra doruğa ulaşırken bağıl nem en alt düzeye iner; karışımla güçlenen yüzey rüzgârı da alevleri besler.'),
  ('Kayak merkezlerindeki kar makinelerinin, hava sıcaklığı 0 °C\'nin biraz üzerinde olsa bile hava çok kuruysa kar üretebilmesinin nedeni nedir?', 'Püskürtülen damlacıkların buharlaşırken soğuyup donabilmesi', ['Makinelerin içinde suyun kimyasal olarak buza dönüştürülmesi', 'Kuru havanın donma noktasının 10 °C olması', 'Kuru havada su damlacıklarının hiç buharlaşmaması'], 'Yapay kar üretiminde belirleyici olan ıslak termometre sıcaklığıdır; kuru havada buharlaşmalı soğuma damlacıkları donma noktasının altına indirebilir.'),
  ('Aşırı soğumuş damlacıklardan oluşan sisin (0 °C\'nin altındaki sis) havalimanlarında bulut tohumlama yöntemiyle dağıtılabilmesinin nedeni nedir?', 'Oluşan buz kristallerinin damlacıklar aleyhine büyüyüp yere düşmesi', ['Tohumlama maddesinin sisi ısıtıp buharlaştırması', 'Tohumlamanın sisi yukarı doğru iterek pistin üzerinde yüksek bir bulut katmanına dönüştürmesi', 'Tohumlamanın rüzgâr üretmesi'], 'Buz kristalleri buharı kendine çeker, damlacıklar buharlaşır; büyüyen kristaller kar gibi düşerek görüşü açar. Bu yöntem 0 °C\'nin üzerindeki sislerde işe yaramaz.'),
  ('Benjamin Franklin 1743\'te Philadelphia\'da bir ay tutulmasını bulutlar yüzünden göremedi, ancak kuzeydoğudaki Boston\'da tutulmanın görüldüğünü ve fırtınanın oraya daha sonra ulaştığını öğrendi. Bu gözlemden çıkardığı sonuç neydi?', 'Fırtınaların, rüzgârın estiği yönden farklı bir yönde ilerleyebileceği', ['Fırtınaların hiç hareket etmediği', 'Ay tutulmalarının fırtınalara yol açtığı', 'Bulutların yalnızca geceleri oluşup gündüz tamamen dağıldığı ve fırtına getirmediği'], 'Fırtınada rüzgâr kuzeydoğudan esiyordu ama sistem güneybatıdan kuzeydoğuya ilerliyordu; bu, fırtınaların hareket eden sistemler olduğu fikrinin erken bir kanıtıydı.'),
  ('Bir ülke kendi meteoroloji uydusu olmadığı hâlde uydu görüntüleriyle tahmin yapabiliyorsa bunun en olası nedeni nedir?', 'Uydu verilerinin uluslararası anlaşmalarla ülkeler arasında paylaşılması', ['Bulutların her ülkeden çıplak gözle aynı biçimde görülmesi', 'Uyduların yalnızca fırlatan ülkenin topraklarını görüntüleyebilmesi ve verinin satılması', 'Tahminlerin uydu verisine hiç ihtiyaç duymaması'], 'Dünya Meteoroloji Örgütü çerçevesinde gözlem ve uydu verilerinin serbest dolaşımı, havanın ülke sınırı tanımaması nedeniyle temel bir ilkedir.'),
  ('Orta enlemlerde tropopozun yüksekliği mevsime göre nasıl değişir?', 'Yazın daha yüksek, kışın daha alçaktadır', ['Kışın daha yüksek, yazın daha alçaktadır', 'Yıl boyunca santimetresi bile değişmez', 'Yalnızca ilkbaharda ortadan kalkar ve yazın yeniden oluşur'], 'Isınan troposfer genleşerek kalınlaşır; yazın sıcak hava kütlelerinin baskın olduğu dönemde tropopoz yükselir, kışın soğuk havada alçalır.'),
  ('Yaz akşamlarında hava radarı görüntülerinde yağış olmadığı hâlde radar çevresinde genişleyen halka biçimli yankılar görülebilir. Bunların en olası kaynağı nedir?', 'Havalanan kuş ve böcek sürüleri', ['Yeraltından yükselen gazlar', 'Radarın gece kapanıp açılırken ürettiği yapay sinyaller', 'Yıldızlardan gelen ışık'], 'Radarlar canlıları da algılar; gün batımında havalanan kuşlar, yarasalar ya da böcekler \'biyolojik yankılar\' oluşturur ve kuş göçü araştırmalarında da kullanılır.'),
  ('Akdeniz çevresindeki yerlerin yağışının büyük bölümünü kış aylarında almasının en iyi meteorolojik açıklaması hangisidir?', 'Kışın subtropikal yüksek basınç güneye çekilir ve siklonlar Akdeniz\'e ulaşır', ['Kışın Güneş ışınları Akdeniz\'e daha dik geldiği için buharlaşma ve yağış artar', 'Kışın muson rüzgârları Hint Okyanusu\'ndan Akdeniz\'e nem taşır', 'Kışın tropikal kasırgalar düzenli olarak Akdeniz\'e girip yağış bırakır'], 'Yazın bölge subtropikal yüksek basıncın alçalan havası altında kurak kalır; kışın bu kuşak güneye kayınca batı rüzgârları ve orta enlem siklonları yağış getirir.'),
  ('Meteorolojik olay sınıflamasında gökkuşağı, hale ve taç (korona) gibi ışığın atmosferdeki kırılma, yansıma ya da kırınımıyla oluşan olaylar hangi gruba girer?', 'Fotometeor', ['Hidrometeor', 'Litometeor', 'Elektrometeor'], 'Fotometeorlar ışığın atmosferdeki tanecikler ya da hava katmanlarıyla etkileşiminden doğan optik olaylardır.'),
  ('Yağış, kar erimesi ve buharlaşma gibi süreçleri akarsu akışı ve taşkın tahmini açısından inceleyen meteoroloji dalına ne ad verilir?', 'Hidrometeoroloji', ['Agrometeoroloji', 'Sinoptik meteoroloji', 'Mikrometeoroloji'], 'Hidrometeoroloji, baraj işletmeciliği ve taşkın uyarıları için yağış tahminlerini akarsu modelleriyle birleştirir.'),
  ('Deniz seviyesinde hava basıncı yaklaşık 101 000 Pa\'dır (N/m²). Yerçekimi ivmesini yaklaşık 10 m/s² alırsak, 1 m² tabanlı ve atmosferin tepesine kadar uzanan bir hava sütununun kütlesi yaklaşık ne kadardır?', '10 ton', ['100 kg', '1 ton', '100 ton'], 'Basınç = ağırlık / alan olduğundan kütle = 101 000 / 10 ≈ 10 100 kg, yani yaklaşık 10 tondur.'),
  ('Sabah erken saatlerde bir fabrika bacasından çıkan dumanın aynı yükseklikte yatay bir şerit hâlinde uzayıp yayılmadığı, öğleden sonra ise duman sütununun aşağı yukarı kıvrılarak dağıldığı görülüyor. Bu fark neyi gösterir?', 'Sabah hava kararlıydı, öğleden sonra ısınmayla kararsızlaştı', ['Sabah hava kararsızdı, öğleden sonra kararlılaştı', 'Hava gün boyu aynıydı; değişen yalnızca bacadan çıkan gazın sıcaklığı ve miktarıydı', 'Sabah rüzgâr yoktu, öğleden sonra yağmur başladı'], 'Kararlı (terselmeli) havada dikey karışım bastırılır ve duman yelpaze gibi yatay yayılır; kararsız havada yükselen ve alçalan akımlar dumanı dalgalandırarak hızla karıştırır.'),
  ('Kış aylarında Balkanlar üzerinden gelen soğuk bir hava kütlesinin Karadeniz\'i geçtikten sonra İstanbul\'a kar getirmesi, Ankara\'ya ise genellikle daha kuru soğuk getirmesi en iyi nasıl açıklanır?', 'Hava denizden nem alır; iç bölgelere ulaşırken dağları aşıp nemini kıyıda bırakır', ['İstanbul\'un deniz seviyesinin altında olması', 'Ankara\'nın ekvatora çok daha yakın olması', 'Karadeniz\'in kışın tamamen donup buhar vermemesi'], 'Soğuk hava görece ılık denizden nem ve ısı alarak kıyılarda kar sağanakları üretir; iç kesimlere ulaşana kadar dağlarda yükselip nemini kaybettiğinden daha kuru kalır.'),
  ('Bir hava haritasında İstanbul ile Ankara arasındaki basınç farkının 4 hPa\'dan 12 hPa\'ya çıktığı görülüyor. Bu değişim iki kent arasındaki bölgede rüzgâr için ne anlama gelir?', 'Basınç gradyanı arttığından rüzgâr güçlenir', ['Basınç farkı arttıkça rüzgâr zayıflar', 'Rüzgârın yönü kesinlikle tersine döner', 'Basınç farkının rüzgâra hiçbir etkisi yoktur'], 'Aynı uzaklıkta daha büyük basınç farkı, basınç gradyan kuvvetinin arttığı anlamına gelir; bu da daha kuvvetli rüzgâr demektir.'),
  ('Bir tropikal siklonun soğuk sulara ve orta enlemlere ilerleyip sıcak çekirdeğini yitirerek cepheli bir alçak basınca dönüşmesine ne ad verilir?', 'Ekstratropikal geçiş', ['Göz duvarı yenilenmesi', 'Fujiwhara etkisi', 'Hızlı yoğunlaşma'], 'Bu geçiş sırasında fırtına zayıflayabilir ama rüzgâr ve yağış alanı genişler; bazı sistemler Avrupa\'ya kadar ulaşarak kuvvetli fırtınalara yol açabilir.'),
  ('Bulutlar oluştukları yüksekliğe göre alçak, orta ve yüksek bulutlar olarak gruplanır. Hangi iki bulut cinsi tabanı alçakta olduğu hâlde çok yükseğe uzanabildiği için ayrıca \'dikey gelişimli bulutlar\' olarak anılır?', 'Kümülüs ve kümülonimbus', ['Sirrus ve sirrostratus', 'Altostratus ve altokümülüs', 'Stratus ve stratokümülüs'], 'Kümülüs türleri yükselen hava akımlarıyla dikey olarak büyür; kümülonimbus tabanı birkaç yüz metrede iken tepesi tropopoza ulaşabilir.'),
  ('Bir gözlemci gökyüzünde gördüğü bulutun sirrostratus mu yoksa altostratus mu olduğunu ayırt etmek istiyor. Aşağıdaki gözlemlerden hangisi bulutun sirrostratus olduğunu en güçlü biçimde destekler?', 'Güneş çevresinde 22°\'lik hale görülmesi', ['Bulutun yağmur yağdırması', 'Bulutun gökyüzünü kalın ve gri bir örtü gibi kaplaması', 'Güneş\'in hiç görünmemesi ve gölgelerin kaybolması'], 'Hale altıgen buz kristallerinde kırılmayla oluşur; buzdan yapılmış ince sirrostratus haleyi sık üretir, altostratusta ise genellikle görülmez.'),
  ('Bir kentin uzun yıllık ortalama yıllık yağışı 600 mm\'dir. Bir yıl bu kentte 450 mm yağış ölçülmüştür. Bu yıl yağış normale göre yüzde kaç eksiktir?', '%25', ['%15', '%33', '%45'], 'Eksik = (600 − 450) / 600 = 150 / 600 = 0,25, yani %25.'),
  ('Açık bir gecede rüzgâr hafif kaldığında yoğun radyasyon sisi oluşurken, rüzgâr belirgin biçimde güçlendiğinde sis yerine yerden biraz yüksekte alçak bir stratus tabakası oluşması neden olur?', 'Kuvvetli rüzgâr soğuyan yer katmanını üstteki havayla karıştırır', ['Rüzgâr sis damlacıklarını dondurup kar yapar', 'Rüzgâr yerdeki ışınım kaybını tamamen durdurarak havanın soğumasını engeller', 'Rüzgâr havadaki nemi uzaya taşır'], 'Radyasyon sisi için çok ince ve sakin bir soğuk katman gerekir; türbülans soğumayı daha kalın bir katmana dağıtır ve yoğuşma yerde değil biraz yukarıda gerçekleşir.'),
  ('Kuvvetli rüzgârlı havalarda, özellikle kar yağışında, standart yağış ölçerlerin gerçek yağıştan daha az ölçmesinin nedeni nedir?', 'Rüzgârın ölçerin ağzı çevresinde akışı bozarak taneleri savurması', ['Rüzgârın ölçerin içindeki suyu dondurması', 'Rüzgârlı havada ölçerin içine düşen yağışın tamamen ve hemen buharlaşması', 'Rüzgârın ölçeri yerinden kaldırması'], 'Ölçerin çevresindeki hızlanan hava hafif tanecikleri, özellikle kar tanelerini ağzın üzerinden taşır; bu yüzden rüzgâr perdeleri kullanılır ve ölçümlere düzeltme uygulanır.'),
  ('Kasırga tahmin haritalarında gösterilen ve giderek genişleyen \'belirsizlik konisi\' için en doğru yorum hangisidir?', 'Koni fırtına merkezinin olası yolunu gösterir; etkiler koninin dışına da taşabilir', ['Koninin dışında kalan yerler fırtınanın hiçbir etkisiyle karşılaşmaz ve önlem gerekmez', 'Koninin genişliği fırtınanın gerçek çapını gösterir', 'Koni fırtınanın yalnızca yağmur alanını gösterir'], 'Koni geçmiş tahmin hatalarından türetilir ve yalnızca merkezin büyük olasılıkla izleyeceği koridoru verir; kuvvetli rüzgâr, kabarma ve yağış yüzlerce kilometre öteye ulaşabilir.'),
  ('Bazı ülkelerin uyarı sistemlerinde \'izleme\' (watch) ve \'uyarı\' (warning) ayrımı yapılır. Bu ayrım en doğru nasıl açıklanır?', 'İzleme koşulların elverişli olduğunu, uyarı olayın başladığını ya da çok yakın olduğunu bildirir', ['İkisi tamamen aynı anlama gelir', 'Uyarı daha hafif, izleme daha ciddi durumlar içindir', 'İzleme yalnızca gece, uyarı yalnızca gündüz yayımlanır'], 'Örneğin hortum izlemesi geniş bir bölgede hortum oluşabileceğini, hortum uyarısı ise radar ya da gözlemle bir hortumun saptandığını ve hemen sığınılması gerektiğini bildirir.'),
  ('Güney Atlas Okyanusu\'nda tropikal kasırgaların çok nadir görülmesinin (ilk belgelenen örnek 2004\'te Brezilya kıyısındaki Catarina\'dır) başlıca nedenleri nelerdir?', 'Görece serin deniz suları ve güçlü üst seviye rüzgâr kesmesi', ['Bölgede Coriolis etkisinin hiç bulunmaması ve havanın dönememesi', 'Bölgenin sürekli buzla kaplı olması', 'Güney Atlantik\'in çok sığ olması'], 'Bu bölgede deniz yüzeyi genellikle siklon için yeterince sıcak değildir ve tropikal yakınsama kuşağı nadiren güneye iner; üst rüzgârların kesmesi de gelişmeyi engeller.'),
  ('Yazın gece boyunca yüzlerce kilometrelik bir alanı kaplayan ve saatlerce süren, birçok gök gürültülü fırtınanın birleşerek oluşturduğu büyük fırtına kümelerine ne ad verilir?', 'Mezoölçek konvektif sistem', ['Tropikal dalga', 'Kutup alçağı', 'Isıl yüksek basınç'], 'Bu sistemler çoğunlukla gece en güçlü evresine ulaşır; geniş alanlarda yoğun yağış, ani sel ve kuvvetli rüzgârlara yol açabilir.'),
  ('Kümülonimbus bulutlarının tepesindeki örs biçimli yayılmaya Latince olarak verilen ve kulaktaki küçük bir kemiğin adıyla da aynı olan terim hangisidir?', 'İnkus', ['Pileus', 'Velum', 'Arkus'], 'İnkus (incus) Latincede \'örs\' anlamına gelir; orta kulaktaki örs kemiği de aynı adı taşır.'),
  ('Kış sabahı alınan görünür ışık uydu görüntülerinde hem bulutlar hem de karla kaplı arazi beyaz görünür. Ardışık görüntülere bakan bir meteorolog bu ikisini en kolay nasıl ayırt edebilir?', 'Hareket etmeyip yer şekillerine uyan beyaz alanlar kar örtüsüdür', ['Kar her zaman bulutlardan daha koyu ve gri görünür', 'Bulutlar görünür ışıkta hiç görünmediği için tüm beyaz alanlar kardır', 'Kar örtüsü gün içinde bulutlardan daha hızlı yer değiştirir'], 'Bulutlar rüzgârla hareket eder ve biçim değiştirir; kar örtüsü ise vadiler, göller ve dağ sıralarının çizdiği sabit desenleri izler.'),
  ('Sıcaklığı 0 °C\'nin üzerinde olan \'ılık\' bulutlarda yağışı artırmak amacıyla gümüş iyodür yerine tuz gibi suyu çeken (higroskopik) parçacıklar kullanılmasının gerekçesi nedir?', 'İri damlacıklar oluşturarak çarpışma-birleşme sürecini hızlandırmak', ['Bulutu dondurup kar yağdırmak', 'Bulutu ısıtıp buharlaştırarak yağışı başka bölgeye kaydırmak', 'Bulutun elektrik yükünü boşaltmak'], 'Ilık bulutlarda buz süreci işlemez; higroskopik parçacıklar üzerinde büyüyen iri damlalar daha hızlı düşerek küçük damlacıkları toplar ve yağmuru başlatabilir.'),
  ('Radyosonde taşıyan meteoroloji balonları genellikle 20–35 km yükseklikte patlar. Balonun yükseldikçe sonunda patlamasının nedeni nedir?', 'Dış basınç azaldıkça içindeki gaz balonu şişirir ve lastik dayanamaz', ['Yükseklerde hava çok sıcak olduğu için balonun lastiği yumuşayıp erir', 'Balon stratosferde yıldırım çarpmasıyla patlar', 'Uydular balonları yörüngede çarparak patlatır'], 'Yerde birkaç metre çaplı olan balon, basıncın yüzde birkaçına indiği yüksekliklerde çapı kat kat büyüyecek kadar genleşir ve sonunda yırtılır; algılayıcı paraşütle iner.'),
  ('Robert FitzRoy\'un 1860\'larda Britanya limanlarında uyguladığı fırtına uyarı sisteminde denizcilere uyarı nasıl iletiliyordu?', 'Liman direklerine çekilen koni ve silindir biçimli işaretlerle', ['Radyo yayınlarıyla', 'Gemilere gönderilen uydu mesajlarıyla ve radyo anonslarıyla', 'Telefonla tek tek arayarak'], 'Telgrafla merkeze ulaşan uyarılar limanlarda direğe çekilen koni gibi işaretlerle duyuruluyordu; koninin yönü fırtınanın beklenen yönünü gösteriyordu.'),
  ('Bisiklet lastiğini hızla şişirirken pompanın ucunun ısındığı fark edilir. Bu gözlem atmosferde hangi olayın küçük ölçekli bir benzeridir?', 'Alçalan havanın sıkışarak ısınması', ['Yükselen havanın genleşerek soğuması', 'Buzun erirken ısı alması', 'Yıldırım kanalının ışık saçması'], 'Gaz dışarıdan ısı almadan sıkıştırılınca ısınır; fön rüzgârlarında ve yüksek basınç alanlarında alçalan havanın ısınması da aynı adyabatik ilkeye dayanır.'),
  ('1883\'teki Krakatau patlamasından sonraki aylarda dünyanın birçok yerinde gün batımlarının olağanüstü kızıl görünmesi ve bazı yerlerde yangın sanılmasının nedeni nedir?', 'Stratosfere taşınan ince volkanik aerosollerin ışığı saçması', ['Patlamanın Güneş\'in rengini değiştirmesi', 'Okyanus yüzeyinin kızıl renge boyanması', 'Volkanik kül bulutunun kendiliğinden ışık saçarak gökyüzünü aydınlatması'], 'Stratosferdeki ince sülfat ve kül parçacıkları aylarca asılı kalarak alacakaranlıkta uzun yol alan ışığı saçtı; parlak kızıl ve mor gökyüzü dünya çapında gözlendi.'),
  ('Akşam saatlerinde hava sıcaklığı 14 °C, çiğ noktası 9 °C ölçülmüştür. Gece açık ve rüzgârsız geçeceği, en düşük sıcaklığın 8 °C olacağı tahmin ediliyorsa sabah için en olası durum hangisidir?', 'Sis ya da çiy oluşması', ['Kesintisiz kar yağışı', 'Hortum oluşumu', 'Nemin sıfıra inmesi ve havanın tamamen kuruması'], 'Sıcaklığın çiğ noktasına ulaşması ya da altına inmesi beklendiğinde, sakin ve açık gecelerde hava doyar; çiy ve radyasyon sisi olasılığı yükselir.'),
  ('Hiç kirlilik olmayan bir ortamda bile yağmur suyunun pH değerinin 7 değil yaklaşık 5,6 olmasının nedeni nedir?', 'Havadaki karbondioksitin suda çözünüp zayıf karbonik asit oluşturması', ['Yağmur damlalarının bulutta tuzla karışması', 'Yağmur suyunun yere düşmeden önce yerden yükselen kireç tozlarıyla karışması', 'Güneş ışığının suyu asitleştirmesi'], 'Bu doğal asitlik nedeniyle \'asit yağmuru\' terimi genellikle pH\'si yaklaşık 5,6\'nın altında kalan yağışlar için kullanılır.'),
  ('Sıcaklığın gün içinde 2 °C ile 6 °C arasında kaldığı bir günde kar yağışının dağlarda 1500 m\'nin üzerinde görüldüğü, kentte ise yağmur yağdığı rapor ediliyor. Bu durum en iyi hangi kavramla açıklanır?', 'Kar yağışının alt sınırının (kar çizgisinin) belirli bir yükseklikte olması', ['Kentte havanın daha kuru olması', 'Dağlarda Güneş\'in daha güçlü ısıtması', 'Kentlerde yağışın her zaman dolu olarak düşüp yerde eriyerek yağmura benzemesi'], 'Sıcaklık yükseklikle azaldığından yağış belirli bir yükseklikten sonra kar olarak kalır; bunun altında kar taneleri erir ve yağmura dönüşür.'),
  ('Hava kütleleri arasındaki sınırlara \'cephe\' denmesinin yanı sıra, cephelerin geçişiyle hava koşullarının birkaç saat içinde belirgin biçimde değişmesinin temel nedeni nedir?', 'Farklı sıcaklık ve nem özelliklerine sahip havaların yer değiştirmesi', ['Cephelerin Güneş ışığını tamamen engellemesi', 'Cephelerin yerin manyetik alanını değiştirerek havayı ısıtıp soğutması', 'Cephelerin denizlerin tuzluluğunu değiştirmesi'], 'Bir cephe geçtiğinde istasyon bir hava kütlesinden ötekine girer; sıcaklık, nem, rüzgâr yönü ve basınç eğilimi birlikte değişir.'),
  ('Gök gürültülü fırtınalarda dolu, yağmur ve buz taneleri arasındaki çarpışmalar sonucu bulutun genellikle hangi kısmı negatif yükle yüklenir?', 'Orta ve alt kısmı', ['Yalnızca en üst kısmı', 'Bulutun dışındaki hava', 'Bulutun tamamı pozitif yüklenir'], 'Ağır kar topağı taneleri negatif yük alarak bulutun orta-alt kesiminde kalır; hafif buz kristalleri pozitif yükü tepeye taşır. Bu ayrışma yıldırımın kaynağıdır.'),
  ('Bir meteoroloji istasyonunda ölçülen değerlerin bir anda olağandışı biçimde \'sıfır\' ya da çok uç değerler göstermesi durumunda veriler modele verilmeden önce ne yapılır?', 'Kalite denetiminden geçirilerek hatalı değerler ayıklanır', ['Tüm istasyon verileri kalıcı olarak silinir', 'Değerler değiştirilmeden kullanılır', 'Uydular arızalı istasyonu onarmak için yönlendirilir ve veriler beklemeye alınır'], 'Alet arızaları ve iletim hataları sık görülür; otomatik kalite denetimi komşu istasyonlar ve fiziksel sınırlarla karşılaştırarak şüpheli verileri ayıklar.'),
  ('Hava tahmin modellerinin daha küçük ızgara aralığıyla (daha yüksek çözünürlükle) çalıştırılması tahminleri iyileştirebilir. Bu yaklaşımın en önemli sınırlayıcısı nedir?', 'Hesaplama yükünün çok hızlı artması', ['Yüksek çözünürlükte fizik yasalarının değişmesi', 'Küçük ızgarada bulutların hiç oluşmaması', 'Yüksek çözünürlüğün yalnızca gece işe yaraması'], 'Izgara aralığı yarıya indirildiğinde yatayda dört kat daha çok nokta olur, ayrıca daha kısa zaman adımı gerekir; hesap yükü kabaca sekiz-on kat artabilir.'),
  ('Açık deniz rüzgâr santrallerinin aynı güçteki kara santrallerine göre genellikle daha fazla ve daha düzenli enerji üretmesinin meteorolojik nedeni nedir?', 'Deniz yüzeyinde sürtünme az olduğundan rüzgâr daha güçlü ve kararlı eser', ['Deniz üzerinde hava basıncı her zaman sıfıra yakındır', 'Denizde Coriolis etkisi daha güçlü olduğu için rüzgârı iki katına çıkarır', 'Deniz suyu türbinleri soğutarak rüzgârı kendisi üretir'], 'Su yüzeyi ağaç, bina ve tepeler gibi engellerden yoksundur; rüzgâr daha az yavaşlar ve daha az türbülanslıdır, bu da üretimi artırır.'),
  ('Uydu görüntülerinde bir okyanus üzerinde açık hücreli ve kapalı hücreli peteğe benzeyen stratokümülüs desenleri görülür. Bu desenler hangi süreci yansıtır?', 'Sığ konveksiyon hücrelerinde yükselen ve alçalan havanın düzenli dağılımını', ['Okyanus dibindeki volkanların ve sıcak su kaynaklarının konumunu', 'Gemilerin izlediği rotaları', 'Yıldızların bulutlara yansımasını'], 'Bulut katmanı içindeki konveksiyon, ısıtılan bir sıvıdaki hücrelere benzer biçimde düzenli hücreler oluşturur; bulutlu ve açık alanlar yükselen ve alçalan kolları gösterir.'),
  ('\'Analog yöntem\' adı verilen eski bir hava tahmini yaklaşımı neye dayanır?', 'Bugünkü haritaya çok benzeyen geçmiş bir durumu bulup ardından olanları örnek almaya', ['Havanın her gün kesinlikle aynı kalacağını varsaymaya', 'Uzun yılların ortalamalarını kullanmaya', 'Bilgisayarda fizik denklemlerini çözmeye'], 'Analog yöntemde geçmiş arşivden benzer bir durum seçilir; ancak atmosferde birebir aynı durum neredeyse hiç tekrarlanmadığı için başarısı sınırlı kalmıştır.'),
  ('İri bir yağmur damlası, tabanı 1350 m yükseklikte olan bir buluttan saniyede yaklaşık 9 m sabit hızla düşüyor. Damla yere yaklaşık ne kadar sürede ulaşır?', '150 saniye', ['15 saniye', '90 saniye', '1350 saniye'], 'Süre = yol / hız = 1350 / 9 = 150 s, yani 2,5 dakika. Küçük damlalar çok daha yavaş düştüğünden aynı yolu daha uzun sürede alır.'),
  ('İrlanda\'nın Dublin kenti ile aynı enlemlerdeki Sibirya kentleri karşılaştırıldığında Dublin\'in kışlarının çok daha ılık olmasının en önemli meteorolojik nedeni nedir?', 'Egemen batı rüzgârlarının okyanustan ılık denizel hava taşıması', ['Dublin\'in Güneş\'e daha yakın olması', 'Dublin\'in yüksek bir platoda bulunması ve kış güneşini daha uzun süre alması', 'Sibirya\'da hiç rüzgâr esmemesi'], 'Orta enlemlerde rüzgârlar çoğunlukla batıdan eser; kıtaların batı kıyıları okyanusun ılıman havasını alırken iç kesimler kışın aşırı soğuyan karasal hava kütlelerinin etkisindedir.'),
  ('Akdeniz\'de su hortumlarının en sık yaz sonu, sonbahar ve kış başında görülmesinin nedeni nedir?', 'Hâlâ ılık olan deniz yüzeyine soğuk hava gelince kararsızlığın artması', ['Denizin bu mevsimlerde donması', 'Bu mevsimlerde rüzgârın hiç esmemesi', 'Bu mevsimlerde Güneş\'in denizi en çok ısıtması'], 'Yaz boyunca ısınan deniz sonbaharda sıcaklığını korur; üstten soğuk hava girdiğinde alt katman çok kararsızlaşır ve sağanaklarla birlikte su hortumları oluşabilir.'),
  ('Meteorolojik gözlemlerde kullanılan \'yerel saat\' yerine UTC\'nin tercih edilmesinin bir yararı aşağıdakilerden hangisidir?', 'Yaz saati uygulaması gibi değişikliklerin kayıtlarda karışıklık yaratmaması', ['UTC\'nin gece ve gündüzü ortadan kaldırması', 'UTC\'de ölçülen sıcaklıkların yerel saate göre her zaman daha yüksek ve daha doğru olması', 'UTC kullanan istasyonlara yağmur yağmaması'], 'Ülkeler yaz saatine geçip çıktıkça yerel saat değişir; sabit bir zaman ölçeği uzun kayıtların ve uluslararası verilerin tutarlı kalmasını sağlar.'),
  ('Uydu görüntülerinde gelişmiş bir orta enlem siklonunun bulut örtüsü çoğu zaman hangi noktalama işaretine benzetilir?', 'Virgül', ['Ünlem', 'Noktalı virgül', 'Soru işareti'], 'Soğuk cephe boyunca uzanan bulut kuyruğu ile merkez çevresinde kıvrılan bulut başı birlikte \'virgül bulutu\' denen deseni oluşturur; bu desen siklonun olgunlaştığını gösterir.'),
  ('Bir gözlemci alçaktaki kümülüs bulutlarının doğuya, çok yüksekteki sirrus bulutlarının ise kuzeydoğuya doğru hareket ettiğini görüyor. Bu gözlem atmosfer hakkında ne söyler?', 'Rüzgârın yön ve hızı yükseklikle değişmektedir', ['Yükseklerde rüzgâr hiç esmemektedir', 'Bulutların hareketi rüzgârdan bağımsızdır', 'Alçak bulutlar yüksek bulutlardan her zaman daha hızlıdır'], 'Bulutlar bulundukları yükseklikteki rüzgârla taşınır; farklı katmanlardaki bulutların farklı yönlere gitmesi rüzgâr kesmesinin doğrudan bir göstergesidir.'),
  ('Bir gözlemci uzaktaki bir kümülonimbusun örsünün kendi tarafına doğru uzandığını görüyor. Üst seviye rüzgârlar örsü fırtınanın hareket yönüne doğru taşıdığına göre bu gözlem ne düşündürür?', 'Fırtına gözlemcinin bulunduğu yere doğru ilerliyor olabilir', ['Fırtına kesinlikle dağılmak üzeredir', 'Fırtına gözlemciden kesinlikle uzaklaşmaktadır', 'Fırtınanın içinde hiç yağış yoktur'], 'Örs genellikle üst rüzgârların estiği yöne uzanır ve bu yön çoğu zaman fırtınanın ilerleyişiyle uyumludur; örsün yaklaşan yüzünü görmek fırtınanın gelebileceğinin işaretidir.'),
  ('Bir istasyonda bir günün en yüksek sıcaklığı 31 °C, en düşük sıcaklığı 17 °C olarak ölçülmüştür. Bu günün günlük sıcaklık farkı (genliği) ve basit ortalaması kaçtır?', 'Fark 14 °C, ortalama 24 °C', ['Fark 48 °C, ortalama 14 °C', 'Fark 24 °C, ortalama 14 °C', 'Fark 14 °C, ortalama 48 °C'], 'Fark = 31 − 17 = 14 °C; basit günlük ortalama = (31 + 17) / 2 = 24 °C.'),
  ('Bir yerdeki kar örtüsü kalınlığının, gün boyunca hava sıcaklığı 0 °C\'nin altında kaldığı ve güneşli olduğu hâlde yavaş yavaş azaldığı görülüyor. Bunun en olası açıklaması nedir?', 'Karın sıvı hâle geçmeden doğrudan buhara dönüşmesi', ['Karın havadaki azotla tepkimeye girmesi', 'Karın toprağın derinlerine çekilmesi', 'Kalınlık ölçeğinin soğukta büzülmesinden kaynaklanan bir ölçüm hatası olması'], 'Kuru ve güneşli havada kar yüzeyindeki buz, erimeden su buharına dönüşebilir; yüksek ve kurak dağlarda kar kaybının önemli bir kısmı bu yolla olur.'),
  ('Tropik bölgelerde rüzgârların genellikle doğudan esmesi, orta enlemlerde ise batıdan esmesi gemicilikte hangi pratik sonucu doğurmuştur?', 'Yelkenliler Atlantik\'i geçerken giderken alize, dönerken batı rüzgârları kuşağını kullanmıştır', ['Yelkenliler her iki yönde de yalnızca kutup rüzgârlarından yararlanarak yol almıştır', 'Gemiler rüzgârdan bağımsız olarak hep aynı rotayı izlemiştir', 'Bu rüzgârlar yalnızca kara ulaşımını etkilemiştir'], 'Avrupa\'dan Amerika\'ya giden yelkenliler güneye inip alize rüzgârlarıyla batıya, dönüşte daha kuzeyden batı rüzgârlarıyla doğuya yol almıştır.'),
  ('Yıldırım çarpan bir ağacın gövdesinde kabuğun şeritler hâlinde patlayıp koptuğu, bazen gövdenin yarıldığı görülür. Bunun başlıca nedeni nedir?', 'Ağacın içindeki suyun bir anda buharlaşıp genleşmesi', ['Yıldırımın ağacı güçlü biçimde mıknatıslayıp liflerini birbirinden itmesi', 'Gök gürültüsünün ses dalgasının kabuğu sökmesi', 'Yıldırımın ağacın içindeki havayı dondurması'], 'Büyük akım nemli öz odun ve kabuk altından geçerken suyu anında ısıtır; ani buharlaşmanın yarattığı basınç kabuğu patlatır ve gövdeyi yarabilir.'),
  ('Hava radarı görüntülerinde gök gürültülü bir fırtınanın önünde, ondan ayrı olarak ilerleyen ince ve zayıf bir yankı çizgisi görülüyor. Bu çizgi en büyük olasılıkla neyi gösterir?', 'Fırtınadan yayılan soğuk havanın ön sınırını', ['Fırtınanın içindeki en iri dolu tanelerini', 'Radarın kendi arızasını', 'Okyanus kıyısının sınırını'], 'Hamle cephesi havadaki toz, böcek ve yoğunluk farklarını bir çizgi boyunca toplar; radar bu ince çizgiyi zayıf bir yankı olarak gösterir. Bu sınır yeni fırtınaları da tetikleyebilir.'),
  ('Bir bölgede bulut tohumlaması yapıldıktan sonra yağış yağdığı görülmüştür. Tohumlamanın bu yağışı sağladığını kanıtlamak için en önemli eksik bilgi hangisidir?', 'Tohumlama yapılmasaydı ne kadar yağış düşeceği', ['Tohumlama uçağının rengi', 'Tohumlamanın hangi gün yapıldığı', 'Yağışın kaç kişi tarafından görüldüğü ve fotoğraflandığı'], 'Tohumlanan bulut zaten yağış bırakabilecek durumda olabilir; etkinin kanıtlanması için rastgele seçilmiş tohumlanan ve tohumlanmayan bulutların karşılaştırıldığı denetimli deneyler gerekir.'),
  ('Meteoroloji istasyonlarında toprak sıcaklığının farklı derinliklerde ölçülmesi özellikle hangi alan için önemlidir?', 'Tarım; tohum çimlenmesi ve don derinliğinin izlenmesi', ['Havacılık; uçakların yakıt hesabı', 'Denizcilik; dalga yüksekliğinin hesaplanması', 'Uzay araştırmaları; uydu yörüngeleri'], 'Toprak sıcaklığı ekim zamanını, kök gelişimini ve toprağın donup donmadığını belirler; bu nedenle agrometeorolojik gözlemlerin temel parçasıdır.'),
  ('Hava tahmin uygulamalarında aynı kent için \'öğleden sonra %70 sağanak olasılığı\' verildiği hâlde o gün hiç yağmur yağmaması tahminin yanlış olduğunu kanıtlar mı?', 'Hayır; %70 olasılık, benzer günlerin yaklaşık %30\'unda yağış olmayacağını da içerir', ['Evet; %70 olasılık yağmurun kesin yağacağı anlamına gelir', 'Evet; olasılık %50\'nin üzerindeyse yağış zorunludur', 'Hayır; çünkü olasılıklar yalnızca kar için verilir'], 'Olasılıklı tahminlerin doğruluğu tek bir günle değil, çok sayıda tahminin istatistiğiyle değerlendirilir: %70 denen günlerin yaklaşık %70\'inde yağış görülmesi tahminin iyi ayarlı olduğunu gösterir.'),
  ('Kutup bölgelerindeki meteoroloji istasyonlarında hava sıcaklığını ölçmek için cıvalı termometre yerine alkollü termometrelerin tercih edilmesinin nedeni nedir?', 'Cıva yaklaşık −39 °C\'de donduğu için çok düşük sıcaklıkları ölçemez', ['Alkol cıvadan daha ağır olduğu için daha kararlıdır', 'Cıva soğukta buharlaşıp kaybolur', 'Alkollü termometreler yalnızca kutuplarda satılır'], 'Etil alkol −110 °C\'nin altına kadar sıvı kalır; bu nedenle en düşük sıcaklıkları ölçen minimum termometrelerinde de alkol kullanılır.'),
  ('Açık ve sakin bir yaz gecesinden sonra sabah çimenlerin çiyle ıslak olduğu, yanındaki asfalt yolun ise kuru kaldığı görülüyor. Bu farkın en olası nedeni nedir?', 'Asfalt gündüz depoladığı ısı nedeniyle gece çiğ noktasına kadar soğumaz', ['Asfalt su buharını kimyasal olarak yok eder', 'Çimenler kendi içlerinden su pompalayarak çiy üretir', 'Asfaltın üzerindeki hava her zaman daha nemlidir'], 'İnce çim yaprakları ışınımla hızla soğur ve toprağa yalıtılmıştır; asfalt ise gündüz depoladığı ısıyı gece salarak yüzeyini çiğ noktasının üzerinde tutar.'),
  ('Evlerde kullanılan nem alma cihazları ve klimalar havadaki nemi hangi ilkeyle azaltır?', 'Havayı soğuk bir yüzeyden geçirip çiğ noktasının altına soğutarak buharı yoğuşturmak', ['Havadaki su buharını elektrikle oksijene dönüştürmek', 'Havayı ısıtarak su buharını yok etmek', 'Havaya tuz püskürterek nemi görünmez kılmak'], 'Soğutucu yüzeye değen hava çiğ noktasının altına soğur; yoğuşan su toplanıp atılır ve odaya daha kuru hava geri verilir.'),
  ('Radyasyon sislerinin sonbahar ve kış başında yaz aylarına göre daha sık görülmesinin başlıca nedeni nedir?', 'Gecelerin uzaması ve yerin daha uzun süre ışınımla soğuyabilmesi', ['Sonbaharda Güneş\'in daha sıcak olması', 'Sonbaharda havada hiç nem bulunmaması', 'Yaz aylarında rüzgârın hiç esmemesi'], 'Uzun gecelerde yer ve üzerindeki hava daha fazla soğur; yağışlardan sonra nemli kalan toprak ve sakin hava da sis oluşumunu kolaylaştırır.'),
  ('16 yönlü rüzgâr gülünde \'kuzey-kuzeydoğu\' yönü kuzeyden saat yönünde yaklaşık kaç derecedir?', '22,5°', ['11,25°', '45°', '67,5°'], 'Rüzgâr gülü 16 eşit parçaya bölündüğünde her aralık 360 / 16 = 22,5°\'dir; kuzey-kuzeydoğu, kuzey (0°) ile kuzeydoğunun (45°) tam ortasındadır.'),
];
